package com.wiseoldclaude.combat;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Decodes the selected attack style into its in-game name, following RuneLite's attack styles plugin
 * ({@code AttackStylesPlugin#updateAttackStyle} and {@code #getWeaponTypeStyles}, themselves from client
 * script 4525). The weapon's style names come from the game cache, so new weapons decode without a table here;
 * only the two categories the cache leaves without a table need {@link #fallbackStyles(int)}.
 */
public final class AttackStyles
{
	private static final String UNUSED_SLOT = "Other";
	private static final String DEFENSIVE = "Defensive";
	private static final String DEFENSIVE_CASTING = "Defensive Casting";

	/**
	 * Staves expose five style buttons but encode defensive autocast as button four plus the casting-mode varbit,
	 * which lands on slot five.
	 */
	private static final int AUTOCAST_SLOT = 4;
	private static final int DEFENSIVE_AUTOCAST_SLOT = 5;

	private static final int BLUE_MOON_SPEAR_CATEGORY = 22;
	private static final int PARTISAN_CATEGORY = 30;

	private AttackStyles()
	{
	}

	/**
	 * Names the selected style.
	 *
	 * @param styleNames the weapon's style names per slot as the cache spells them ("Accurate", "Other", ...)
	 * @param styleIndex the selected style button ({@code VarPlayerID.COM_MODE})
	 * @param castingMode the autocast mode ({@code VarbitID.AUTOCAST_DEFMODE}), 1 when autocasting defensively
	 * @return the style name, or null when the slot is unused or out of range, so an unknown style is never
	 *   reported as a real one
	 */
	public static String decode(List<String> styleNames, int styleIndex, int castingMode)
	{
		if (styleIndex < 0 || styleIndex >= styleNames.size())
		{
			return null;
		}
		int slot = styleIndex == AUTOCAST_SLOT ? styleIndex + castingMode : styleIndex;
		if (slot >= styleNames.size())
		{
			return null;
		}
		String name = styleNames.get(slot);
		if (UNUSED_SLOT.equals(name))
		{
			return null;
		}
		return slot == DEFENSIVE_AUTOCAST_SLOT && DEFENSIVE.equals(name) ? DEFENSIVE_CASTING : name;
	}

	/**
	 * Style names for the weapon categories the cache's weapon-styles enum has no entry for, copied from
	 * RuneLite's hardcoded tables.
	 *
	 * @param weaponCategory {@code VarbitID.COMBAT_WEAPON_CATEGORY}
	 * @return the style names per slot, empty when the category is unknown
	 */
	public static List<String> fallbackStyles(int weaponCategory)
	{
		if (weaponCategory == BLUE_MOON_SPEAR_CATEGORY)
		{
			return Arrays.asList("Accurate", "Aggressive", UNUSED_SLOT, DEFENSIVE, "Casting", DEFENSIVE);
		}
		if (weaponCategory == PARTISAN_CATEGORY)
		{
			return Arrays.asList("Accurate", "Aggressive", "Aggressive", DEFENSIVE);
		}
		return Collections.emptyList();
	}
}

package com.wiseoldclaude.combat;

import java.util.Arrays;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.api.Prayer;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Decides which variable changes make the snapshot's combat state or status stale, so a prayer flick or a
 * poisoning is written while the player stands still. Countdowns kept in ticks (divine potions, moonlight
 * potion, teleblock) are deliberately not watched: they change every tick and would force a write every
 * interval for the potion's whole duration; their seconds refresh with the next write and are read relative to
 * the snapshot's {@code capturedAt}.
 */
public final class CombatVarWatch
{
	private static final Set<Integer> VARPS = Set.of(
		VarPlayerID.COM_MODE,
		VarPlayerID.SA_ENERGY,
		VarPlayerID.POISON,
		VarPlayerID.DISEASE);

	private static final Set<Integer> VARBITS = Stream.concat(
		Stream.of(
			VarbitID.COMBAT_WEAPON_CATEGORY,
			VarbitID.AUTOCAST_DEFMODE,
			VarbitID.SPELLBOOK,
			VarbitID.STAMINA_ACTIVE,
			VarbitID.STAMINA_DURATION,
			VarbitID.ANTIFIRE_POTION,
			VarbitID.SUPER_ANTIFIRE_POTION,
			VarbitID.NZONE_OVERLOAD_POTION_EFFECTS,
			VarbitID.RAIDS_OVERLOAD_TIMER),
		Arrays.stream(Prayer.values()).map(Prayer::getVarbit))
		.collect(Collectors.toUnmodifiableSet());

	private CombatVarWatch()
	{
	}

	/**
	 * Whether a {@code VarbitChanged} event touches exported combat or status state.
	 *
	 * @param varpId the changed varp
	 * @param varbitId the changed varbit, -1 when the event is for a whole varp
	 * @return true when the snapshot should be rewritten
	 */
	public static boolean affectsSnapshot(int varpId, int varbitId)
	{
		return VARPS.contains(varpId) || VARBITS.contains(varbitId);
	}
}

package com.wiseoldclaude.combat;

import lombok.Builder;
import lombok.Value;

/**
 * Raw values of the varbits and varps behind timed effects, read on the client thread and decoded by
 * {@link TimedEffects}. Each field names its source; units differ per effect and are applied by the decoder.
 * Unset fields default to zero, which every source uses for "not active".
 */
@Value
@Builder
public class TimedEffectVars
{
	/** {@code VarbitID.STAMINA_ACTIVE}: 1 while a stamina effect runs. */
	int staminaActive;
	/** {@code VarbitID.STAMINA_DURATION}: remaining time in 10-tick units. */
	int staminaDuration;
	/** {@code VarbitID.ANTIFIRE_POTION}: remaining 30-tick steps. */
	int antifire;
	/** {@code VarbitID.SUPER_ANTIFIRE_POTION}: remaining 20-tick steps. */
	int superAntifire;
	/** {@code VarPlayerID.POISON}: negative while antipoison or antivenom protects. */
	int poison;
	/** {@code VarbitID.NZONE_OVERLOAD_POTION_EFFECTS}: remaining 25-tick steps. */
	int nmzOverload;
	/** {@code VarbitID.RAIDS_OVERLOAD_TIMER}: remaining 25-tick steps. */
	int raidsOverload;
	/** {@code VarbitID.DIVINEATTACK_POTION_TIME}, in ticks, as are the other divine and moonlight fields. */
	int divineSuperAttack;
	/** {@code VarbitID.DIVINESTRENGTH_POTION_TIME}. */
	int divineSuperStrength;
	/** {@code VarbitID.DIVINEDEFENCE_POTION_TIME}. */
	int divineSuperDefence;
	/** {@code VarbitID.DIVINERANGE_POTION_TIME}. */
	int divineRanging;
	/** {@code VarbitID.DIVINEMAGIC_POTION_TIME}. */
	int divineMagic;
	/** {@code VarbitID.DIVINECOMBAT_POTION_TIME}. */
	int divineSuperCombat;
	/** {@code VarbitID.DIVINEBASTION_POTION_TIME}. */
	int divineBastion;
	/** {@code VarbitID.DIVINEBATTLEMAGE_POTION_TIME}. */
	int divineBattlemage;
	/** {@code VarbitID.MOONLIGHT_POTION_TIME}. */
	int moonlightPotion;
	/** {@code VarbitID.TELEBLOCK_CYCLES}: remaining ticks plus 100. */
	int teleblock;
}

package com.wiseoldclaude.combat;

/**
 * Converts an actor's health bar into a percentage. The server only sends health as a fraction of a bar
 * ({@code Actor#getHealthRatio} over {@code Actor#getHealthScale}), and only once the bar has been shown.
 */
public final class HealthPercent
{
	private HealthPercent()
	{
	}

	/**
	 * Rounds up so a target with any health left never reads as 0% (dead).
	 *
	 * @param ratio the filled part of the bar, -1 when unknown
	 * @param scale the bar's full size, -1 when unknown
	 * @return the percentage from 0 to 100, or null when the bar has not been seen
	 */
	public static Integer of(int ratio, int scale)
	{
		if (ratio < 0 || scale <= 0)
		{
			return null;
		}
		return (int) Math.ceil(100.0 * ratio / scale);
	}
}

package com.wiseoldclaude.combat;

import lombok.Value;

/**
 * Whether Deadeye and Mystic Vigour replace Eagle Eye and Mystic Might. The upgrades share their base prayer's
 * slot, so the prayer varbits alone cannot tell which one is on; RuneLite's prayer plugin
 * ({@code PrayerType.DEADEYE#isEnabled}) settles it from the unlock varbits and Last Man Standing, where the
 * upgrades are unavailable.
 */
@Value
public class PrayerUpgrades
{
	boolean deadeye;
	boolean mysticVigour;

	/**
	 * Reads the upgrade state from its varbits.
	 *
	 * @param deadeyeUnlocked {@code VarbitID.PRAYER_DEADEYE_UNLOCKED}
	 * @param mysticVigourUnlocked {@code VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED}
	 * @param inLastManStanding {@code VarbitID.BR_INGAME}
	 * @return which upgrades are in effect
	 */
	public static PrayerUpgrades fromVarbits(int deadeyeUnlocked, int mysticVigourUnlocked, int inLastManStanding)
	{
		boolean upgradesAllowed = inLastManStanding == 0;
		return new PrayerUpgrades(upgradesAllowed && deadeyeUnlocked != 0, upgradesAllowed && mysticVigourUnlocked != 0);
	}
}

package com.wiseoldclaude.combat;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.Prayer;

/**
 * Names the prayers that are on. Reads each prayer's varbit rather than the deprecated
 * {@code Client#isPrayerActive}, which RuneLite documents as mishandling the Deadeye and Mystic Vigour slots,
 * and resolves those slots with {@link PrayerUpgrades}.
 */
public final class ActivePrayers
{
	private static final String RUINOUS_POWERS_PREFIX = "RP_";
	private static final Set<String> CONNECTING_WORDS = Set.of("of", "from");

	private ActivePrayers()
	{
	}

	/**
	 * Names the active prayers.
	 *
	 * @param varbitsOn prayers whose varbit is non-zero
	 * @param upgrades which shared slots hold the upgraded prayer
	 * @return display names in prayer-book order
	 */
	public static List<String> names(Set<Prayer> varbitsOn, PrayerUpgrades upgrades)
	{
		List<String> names = new ArrayList<>();
		for (Prayer prayer : Prayer.values())
		{
			if (varbitsOn.contains(prayer) && isInEffect(prayer, upgrades))
			{
				names.add(displayName(prayer));
			}
		}
		return names;
	}

	private static boolean isInEffect(Prayer prayer, PrayerUpgrades upgrades)
	{
		switch (prayer)
		{
			case EAGLE_EYE:
				return !upgrades.isDeadeye();
			case DEADEYE:
				return upgrades.isDeadeye();
			case MYSTIC_MIGHT:
				return !upgrades.isMysticVigour();
			case MYSTIC_VIGOUR:
				return upgrades.isMysticVigour();
			default:
				return true;
		}
	}

	/**
	 * Derives the in-game name from RuneLite's constant ({@code PROTECT_FROM_MELEE} becomes "Protect from Melee");
	 * the Ruinous Powers prefix is dropped because the game shows those prayers without it.
	 *
	 * @param prayer the prayer
	 * @return the display name
	 */
	public static String displayName(Prayer prayer)
	{
		String constant = prayer.name();
		if (constant.startsWith(RUINOUS_POWERS_PREFIX))
		{
			constant = constant.substring(RUINOUS_POWERS_PREFIX.length());
		}
		List<String> words = Arrays.asList(constant.toLowerCase(Locale.ROOT).split("_"));
		return words.stream()
			.map(word -> CONNECTING_WORDS.contains(word) ? word : capitalise(word))
			.collect(Collectors.joining(" "));
	}

	private static String capitalise(String word)
	{
		return Character.toUpperCase(word.charAt(0)) + word.substring(1);
	}
}

package com.wiseoldclaude.combat;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Decodes timed effects into seconds left, mirroring the units and rules of RuneLite's timers and buffs plugin
 * ({@code TimersAndBuffsPlugin#onVarbitChanged}). Effects counted down in multi-tick steps (antifire, super
 * antifire, overload, stamina, antipoison, antivenom) only know which step they are in, so their seconds are an
 * upper bound accurate to one step.
 */
public final class TimedEffects
{
	private static final int ANTIFIRE_STEP_TICKS = 30;
	private static final int SUPER_ANTIFIRE_STEP_TICKS = 20;
	private static final int STAMINA_STEP_TICKS = 10;
	private static final int OVERLOAD_STEP_TICKS = 25;
	private static final int POISON_STEP_TICKS = 30;

	/** Antivenom protection is encoded below this poison value, antipoison between it and zero. */
	private static final int VENOM_PROTECTION_CUTOFF = -38;

	private static final int TELEBLOCK_OFFSET = 100;

	private TimedEffects()
	{
	}

	/**
	 * Lists the effects in force. A divine potion whose effect is already covered by a combined potion lasting at
	 * least as long (for example divine super attack under divine super combat) is left out, as RuneLite's timers
	 * do, so one potion is not reported as four.
	 *
	 * @param vars the raw values
	 * @return effect name to whole seconds left, empty when nothing is active
	 */
	public static Map<String, Integer> decode(TimedEffectVars vars)
	{
		Map<String, Integer> effects = new LinkedHashMap<>();
		if (vars.getStaminaActive() == 1)
		{
			putTicks(effects, "Stamina", vars.getStaminaDuration() * STAMINA_STEP_TICKS);
		}
		putTicks(effects, "Antifire", vars.getAntifire() * ANTIFIRE_STEP_TICKS);
		putTicks(effects, "Super antifire", vars.getSuperAntifire() * SUPER_ANTIFIRE_STEP_TICKS);
		putPoisonProtection(effects, vars.getPoison());
		putTicks(effects, "Overload", Math.max(vars.getNmzOverload(), vars.getRaidsOverload()) * OVERLOAD_STEP_TICKS);
		putDivinePotions(effects, vars);
		putTicks(effects, "Teleblock", vars.getTeleblock() - TELEBLOCK_OFFSET);
		return effects;
	}

	private static void putPoisonProtection(Map<String, Integer> effects, int poison)
	{
		if (poison < VENOM_PROTECTION_CUTOFF)
		{
			putTicks(effects, "Antivenom", (VENOM_PROTECTION_CUTOFF - poison) * POISON_STEP_TICKS);
		}
		else if (poison < 0)
		{
			putTicks(effects, "Antipoison", -poison * POISON_STEP_TICKS);
		}
	}

	private static void putDivinePotions(Map<String, Integer> effects, TimedEffectVars vars)
	{
		int combat = vars.getDivineSuperCombat();
		int bastion = vars.getDivineBastion();
		int battlemage = vars.getDivineBattlemage();
		int moonlight = vars.getMoonlightPotion();
		int moonlightCover = moonlight > 0 ? moonlight + 1 : 0;
		int defenceCover = Math.max(Math.max(combat, bastion), Math.max(battlemage, moonlightCover));
		putTicks(effects, "Divine super attack", uncovered(vars.getDivineSuperAttack(), combat));
		putTicks(effects, "Divine super strength", uncovered(vars.getDivineSuperStrength(), combat));
		putTicks(effects, "Divine super defence", uncovered(vars.getDivineSuperDefence(), defenceCover));
		putTicks(effects, "Divine ranging", uncovered(vars.getDivineRanging(), bastion));
		putTicks(effects, "Divine magic", uncovered(vars.getDivineMagic(), battlemage));
		putTicks(effects, "Divine super combat", combat);
		putTicks(effects, "Divine bastion", bastion);
		putTicks(effects, "Divine battlemage", battlemage);
		putTicks(effects, "Moonlight potion", moonlight);
	}

	/**
	 * A single-stat potion's remaining ticks, unless a combined potion covers it. Moonlight potion's cover counts one
	 * tick extra because the game can leave divine super defence one tick ahead of it after a re-dose, which RuneLite
	 * also tolerates.
	 *
	 * @param ticks the single-stat potion's remaining ticks
	 * @param coveringTicks the remaining ticks of the combined potion that would cover it
	 * @return the single-stat potion's ticks, or 0 when the combined potion outlasts it, which leaves it unlisted
	 */
	private static int uncovered(int ticks, int coveringTicks)
	{
		return ticks > coveringTicks ? ticks : 0;
	}

	private static void putTicks(Map<String, Integer> effects, String name, int ticks)
	{
		if (ticks > 0)
		{
			effects.put(name, secondsFor(ticks));
		}
	}

	private static int secondsFor(int ticks)
	{
		return (ticks * 3 + 4) / 5;
	}
}

package com.wiseoldclaude.nearby;

import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * One scene object as the client describes it after impostor resolution. Plain data, so deciding what is
 * worth indexing can be tested without a running client.
 */
@Value
public class ObjectSighting implements Sighting
{
	int id;
	String name;
	String[] actions;

	/**
	 * The tile RuneLite reports for the object: for objects larger than one tile, the centre tile rounded
	 * south-west, so every tile a large object covers reports the same one.
	 */
	WorldPoint tile;
}

package com.wiseoldclaude.nearby;

import java.util.Comparator;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

/** The order and cap every nearby index shares: nearest the player first, and only as many as the file allows. */
final class SceneRanking
{
	private SceneRanking()
	{
	}

	/**
	 * Distance first, then every identifying field, so equal-distance sightings always come out in the same order
	 * and an unchanged scene produces an identical index, which is what lets an unchanged scene skip the write.
	 *
	 * @param origin the player's tile
	 * @param <T> the kind of sighting
	 * @return the nearest-first order
	 */
	static <T extends Sighting> Comparator<T> nearestFirst(WorldPoint origin)
	{
		return Comparator.<T>comparingInt(sighting -> origin.distanceTo2D(sighting.getTile()))
			.thenComparing(Sighting::getName)
			.thenComparingInt(sighting -> sighting.getTile().getX())
			.thenComparingInt(sighting -> sighting.getTile().getY())
			.thenComparingInt(sighting -> sighting.getTile().getPlane())
			.thenComparingInt(Sighting::getId);
	}

	/**
	 * @param ranked entries nearest first
	 * @param max most entries the file may hold
	 * @param <T> the kind of entry
	 * @return the nearest {@code max} entries, or all of them when there are fewer
	 */
	static <T> List<T> keepNearest(List<T> ranked, int max)
	{
		return ranked.subList(0, Math.min(max, ranked.size()));
	}
}

package com.wiseoldclaude.nearby;

import com.google.gson.Gson;
import com.wiseoldclaude.io.CharacterFileWriter;
import com.wiseoldclaude.io.OutputDirectory;
import com.wiseoldclaude.model.NearbyNpcs;
import java.io.IOException;
import javax.inject.Inject;
import net.runelite.client.util.Filepath;

/**
 * Persists the nearby-NPC index as one file per character under {@code npcs/}.
 */
public class NearbyNpcsWriter
{
	static final String NPCS_DIR = "npcs";

	private final CharacterFileWriter files;

	/**
	 * Writes nulls, as the file format requires.
	 *
	 * @param gson the client's shared Gson
	 * @param directory where the plugin's files go
	 */
	@Inject
	public NearbyNpcsWriter(Gson gson, OutputDirectory directory)
	{
		this.files = CharacterFileWriter.writingNulls(gson, directory).in(NPCS_DIR);
	}

	/**
	 * Writes the file, replacing any previous one for the same character.
	 *
	 * @param index the value to persist
	 * @return the written file
	 * @throws IOException if the directory cannot be created or the file cannot be written
	 */
	public Filepath write(NearbyNpcs index) throws IOException
	{
		return files.write(index.getRsn(), index);
	}
}

