package com.wiseoldclaude.nearby;

import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * One NPC as the client describes it after multi-NPC transformation. Plain data, so deciding what is worth
 * indexing can be tested without a running client.
 */
@Value
public class NpcSighting implements Sighting
{
	int id;
	String name;

	/**
	 * As the client reports it, where -1 means the NPC has no combat level.
	 */
	int combatLevel;
	String[] actions;

	/**
	 * Whether the client offers any menu option on the NPC; scenery-like NPCs that only animate are not.
	 */
	boolean interactible;

	/**
	 * The NPC's server-side tile, which can be a tile ahead of where the client draws a walking NPC.
	 */
	WorldPoint tile;
}

package com.wiseoldclaude.nearby;

import com.wiseoldclaude.common.WriteThrottle;
import com.wiseoldclaude.io.BackgroundWrites;
import com.wiseoldclaude.model.NearbyObjects;
import java.time.Duration;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;

/**
 * Keeps the nearby-object file current. Object spawn and despawn events mark the index dirty, and a rebuild follows
 * at most once per interval. Starts dirty, so the scene is written once after the plugin starts even when no object
 * event arrives. Call {@link #onTick} on the client thread, where object definitions are safe to read; the write
 * itself runs on the executor.
 */
@Slf4j
public class NearbyObjectRefresh
{
	/**
	 * Six seconds between rebuilds. Spawns and despawns arrive in bursts (a scene load fires one per object, a busy
	 * woodcutting spot one per chop), and a rebuild walks the whole scene, so a burst costs one walk. Short enough
	 * that a tree chopped down is gone from the index before the player can ask again.
	 */
	static final int INTERVAL_TICKS = 10;

	private final Supplier<NearbyObjects> source;
	private final Consumer<NearbyObjects> sink;
	private final WriteThrottle throttle = new WriteThrottle(INTERVAL_TICKS);

	/**
	 * Collects with the client and writes into the plugin's output directory off the client thread.
	 *
	 * @param collector reads the scene's objects
	 * @param writer persists an index
	 * @param executor the client's background executor, so disk writes never stall a frame
	 */
	@Inject
	public NearbyObjectRefresh(NearbyObjectsCollector collector, NearbyObjectsWriter writer,
		ScheduledExecutorService executor)
	{
		this(collector::collect, BackgroundWrites.on(executor, writer::write, "nearby objects"));
	}

	/**
	 * @param source the current index, or null while no character is loaded
	 * @param sink receives each index worth writing
	 */
	NearbyObjectRefresh(Supplier<NearbyObjects> source, Consumer<NearbyObjects> sink)
	{
		this.source = source;
		this.sink = sink;
		throttle.markDirty();
	}

	/**
	 * Records that objects appeared or disappeared, that a new scene was loaded, or that the plugin restarted.
	 */
	public void markDirty()
	{
		throttle.markDirty();
	}

	/**
	 * Rebuilds the index when objects changed and the interval has elapsed. A tick without a loaded character keeps
	 * the change pending for a later tick. The rebuild's duration is logged at debug level so its cost can be
	 * checked in a developer-mode client.
	 *
	 * @param tick current game tick count
	 */
	public void onTick(int tick)
	{
		if (!throttle.tryAcquire(tick))
		{
			return;
		}
		long started = System.nanoTime();
		NearbyObjects index = source.get();
		if (index == null)
		{
			throttle.markDirty();
			return;
		}
		log.debug("Indexed {} nearby objects in {} ms", countTiles(index),
			Duration.ofNanos(System.nanoTime() - started).toMillis());
		sink.accept(index);
	}

	private static int countTiles(NearbyObjects index)
	{
		return index.getObjects().values().stream().mapToInt(List::size).sum();
	}
}

package com.wiseoldclaude.nearby;

import com.wiseoldclaude.common.WriteThrottle;
import com.wiseoldclaude.io.BackgroundWrites;
import com.wiseoldclaude.model.GroundItems;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.inject.Inject;

/**
 * Keeps the ground-item file current. Ground items never move, so unlike NPCs they need no polling: the
 * client's item spawn, despawn and quantity events mark the index dirty, and a rebuild follows at most once
 * per interval. Starts dirty, so a plugin enabled mid-session, when no spawn event will arrive for the items
 * already lying around, still writes the scene once. Call {@link #onTick} on the client thread, where item
 * definitions are safe to read; the write itself runs on the executor.
 */
public class GroundItemRefresh
{
	/**
	 * Two ticks (1.2 seconds) at most between rebuilds. Item events are frequent (every drop, pickup and
	 * despawn in the scene, and one per item when a scene loads) and a rebuild walks every scene tile, so a
	 * burst must cost one walk; but "what dropped?" is asked right after a kill, so the drop must already be
	 * in the file by the time the player has typed the question.
	 */
	static final int INTERVAL_TICKS = 2;

	private final Supplier<GroundItems> source;
	private final Consumer<GroundItems> sink;
	private final WriteThrottle throttle = new WriteThrottle(INTERVAL_TICKS);
	private GroundItems lastPublished;

	/**
	 * Collects with the client and writes into the plugin's output directory off the client thread.
	 *
	 * @param collector reads the scene's ground items
	 * @param writer persists an index
	 * @param executor the client's background executor, so disk writes never stall a frame
	 */
	@Inject
	public GroundItemRefresh(GroundItemsCollector collector, GroundItemsWriter writer,
		ScheduledExecutorService executor)
	{
		this(collector::collect, BackgroundWrites.on(executor, writer::write, "ground items"));
	}

	/**
	 * @param source the current index, or null while no character is loaded
	 * @param sink receives each index worth writing
	 */
	GroundItemRefresh(Supplier<GroundItems> source, Consumer<GroundItems> sink)
	{
		this.source = source;
		this.sink = sink;
		throttle.markDirty();
	}

	/**
	 * Records that items appeared, disappeared or changed quantity, or that a new scene was loaded.
	 */
	public void markDirty()
	{
		throttle.markDirty();
	}

	/**
	 * Rebuilds the index when items changed and the interval has elapsed, and publishes it if anything but the
	 * capture time changed. A tick without a loaded character keeps the change pending for a later tick.
	 *
	 * @param tick current game tick count
	 */
	public void onTick(int tick)
	{
		if (!throttle.tryAcquire(tick))
		{
			return;
		}
		GroundItems index = source.get();
		if (index == null)
		{
			throttle.markDirty();
			return;
		}
		GroundItems comparable = index.toBuilder().capturedAt(null).build();
		if (comparable.equals(lastPublished))
		{
			return;
		}
		lastPublished = comparable;
		sink.accept(index);
	}
}

package com.wiseoldclaude.nearby;

import com.wiseoldclaude.common.GameNames;
import com.wiseoldclaude.model.GroundItemVariant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;
import lombok.Value;
import net.runelite.api.TileItem;
import net.runelite.api.coords.WorldPoint;

/**
 * Reduces the items on the ground around the player to named stacks grouped by name, then by id and
 * ownership. Several unstackable items of one kind on one tile become one stack with their summed quantity,
 * the way the client's own ground-item labels count them, so a kill tile of three bones costs one entry.
 */
public class GroundItemIndex
{
	private final int maxStacks;

	/**
	 * @param maxStacks most stacks to keep; past it only the ones nearest the origin survive, so a cluttered
	 *   scene (a Grand Exchange drop party) cannot grow the file without bound while the stacks the player can
	 *   reach soonest remain
	 */
	public GroundItemIndex(int maxStacks)
	{
		this.maxStacks = maxStacks;
	}

	/**
	 * Builds the index from every item the scene's tiles hold.
	 *
	 * @param origin the player's tile, which defines "nearest" for ordering and the cap
	 * @param sightings every item on the ground
	 * @return item name, alphabetically, to its variants; variants and their stacks nearest first
	 */
	public IndexedGroundItems index(WorldPoint origin, Collection<GroundItemSighting> sightings)
	{
		List<Stack> ranked = mergeByTile(sightings).stream()
			.sorted(nearestFirst(origin))
			.collect(Collectors.toList());

		Map<String, Map<VariantKey, GroundItemVariant>> grouped = new TreeMap<>();
		for (Stack stack : SceneRanking.keepNearest(ranked, maxStacks))
		{
			grouped.computeIfAbsent(stack.sighting.getName(), name -> new LinkedHashMap<>())
				.computeIfAbsent(stack.key(), key -> stack.toVariant())
				.getStacks().add(stack.toTuple());
		}

		Map<String, List<GroundItemVariant>> items = new TreeMap<>();
		grouped.forEach((name, variants) -> items.put(name, new ArrayList<>(variants.values())));
		return new IndexedGroundItems(items, ranked.size() > maxStacks);
	}

	/**
	 * Names the client's ownership code. A code this plugin does not know is reported as another player's, so
	 * an unfamiliar stack is never suggested to an ironman who could not take it.
	 *
	 * @param code one of the {@code TileItem.OWNERSHIP_*} constants
	 * @return the ownership name written to the file
	 */
	static String ownershipName(int code)
	{
		switch (code)
		{
			case TileItem.OWNERSHIP_NONE:
				return "none";
			case TileItem.OWNERSHIP_SELF:
				return "self";
			case TileItem.OWNERSHIP_GROUP:
				return "group";
			default:
				return "other";
		}
	}

	private static Collection<Stack> mergeByTile(Collection<GroundItemSighting> sightings)
	{
		Map<List<Object>, Stack> stacks = new LinkedHashMap<>();
		for (GroundItemSighting sighting : sightings)
		{
			if (GameNames.isNamed(sighting.getName()))
			{
				stacks.computeIfAbsent(Stack.identity(sighting), identity -> new Stack(sighting))
					.quantity += sighting.getQuantity();
			}
		}
		return stacks.values();
	}

	/**
	 * The shared nearest-first order, then ownership and quantity, which only stacks have.
	 */
	private static Comparator<Stack> nearestFirst(WorldPoint origin)
	{
		return Comparator.comparing((Stack stack) -> stack.sighting, SceneRanking.<GroundItemSighting>nearestFirst(origin))
			.thenComparing(stack -> ownershipName(stack.sighting.getOwnership()))
			.thenComparingInt(stack -> stack.quantity);
	}

	/**
	 * Identifies a variant within one name: the id fixes the item and its prices, the ownership who may take it.
	 */
	@Value
	private static class VariantKey
	{
		int id;
		String ownership;
	}

	/**
	 * Every item of one id and ownership on one tile, with their quantities summed.
	 */
	private static final class Stack
	{
		private final GroundItemSighting sighting;
		private int quantity;

		private Stack(GroundItemSighting sighting)
		{
			this.sighting = sighting;
		}

		private static List<Object> identity(GroundItemSighting sighting)
		{
			return Arrays.asList(sighting.getName(), sighting.getId(), ownershipName(sighting.getOwnership()),
				sighting.getTile());
		}

		private VariantKey key()
		{
			return new VariantKey(sighting.getId(), ownershipName(sighting.getOwnership()));
		}

		private GroundItemVariant toVariant()
		{
			return new GroundItemVariant(sighting.getId(), ownershipName(sighting.getOwnership()),
				Math.max(0, sighting.getGePrice()), Math.max(0, sighting.getHaPrice()), new ArrayList<>());
		}

		private List<Integer> toTuple()
		{
			WorldPoint tile = sighting.getTile();
			return Arrays.asList(tile.getX(), tile.getY(), tile.getPlane(), quantity);
		}
	}
}

package com.wiseoldclaude.nearby;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * One item on a tile as the client lists it, with its prices already looked up. Plain data, so grouping and
 * capping can be tested without a running client.
 */
@Value
@AllArgsConstructor
@Builder(toBuilder = true)
public class GroundItemSighting implements Sighting
{
	int id;
	String name;
	int quantity;

	/**
	 * The client's ownership code, one of the {@code TileItem.OWNERSHIP_*} constants.
	 */
	int ownership;
