	 * @return the definition id
	 */
	int getId();

	/**
	 * @return the definition's name, possibly a placeholder
	 */
	String getName();

	/**
	 * @return where it was seen
	 */
	WorldPoint getTile();
}

package com.wiseoldclaude.nearby;

import com.wiseoldclaude.common.Positions;
import com.wiseoldclaude.model.NearbyNpcs;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;

/**
 * Adapter that reads the client's NPC list into a {@link NearbyNpcs} index. Kept free of logic beyond
 * mapping; what is worth indexing is decided by {@link NearbyNpcIndex}. Reads only {@link WorldView#npcs()},
 * which never contains other players. Must be called on the client thread: NPC definitions and the varbits
 * that select a multi-NPC's current form are only safe to read there.
 */
public class NearbyNpcsCollector
{
	/**
	 * A busy scene holds an estimated one to three hundred NPCs; this keeps all of them while bounding a
	 * pathological scene's file to a few tens of kilobytes.
	 */
	static final int MAX_NPCS = 1000;

	private final Client client;
	private final NearbyNpcIndex index = new NearbyNpcIndex(MAX_NPCS);

	@Inject
	public NearbyNpcsCollector(Client client)
	{
		this.client = client;
	}

	/**
	 * Indexes the NPCs around the logged-in character.
	 *
	 * @return the index, or null while no player or scene is loaded (login screen, hopping)
	 */
	public NearbyNpcs collect()
	{
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (player == null || player.getName() == null || view == null)
		{
			return null;
		}

		WorldPoint origin = player.getWorldLocation();
		IndexedNpcs indexed = index.index(origin, sightingsIn(view));
		return NearbyNpcs.builder()
			.rsn(player.getName())
			.capturedAt(Instant.now().toString())
			.world(client.getWorld())
			.instance(view.isInstance())
			.origin(Positions.of(origin))
			.truncated(indexed.isTruncated())
			.npcs(indexed.getNpcs())
			.build();
	}

	/**
	 * Records each NPC as the player currently sees it. Multi-NPCs carry a placeholder definition whose real
	 * name and options come from the form the player's varbits select, which
	 * {@link NPC#getTransformedComposition()} resolves; null means the NPC is hidden for this player.
	 * Followers are skipped: a pet belongs to a player, and other players' data is out of scope.
	 */
	private static List<NpcSighting> sightingsIn(WorldView view)
	{
		List<NpcSighting> sightings = new ArrayList<>();
		for (NPC npc : view.npcs())
		{
			NPCComposition composition = npc.getTransformedComposition();
			if (composition == null || composition.isFollower())
			{
				continue;
			}
			sightings.add(new NpcSighting(composition.getId(), composition.getName(), composition.getCombatLevel(),
				composition.getActions(), composition.isInteractible(), npc.getWorldLocation()));
		}
		return sightings;
	}
}

package com.wiseoldclaude.nearby;

import com.wiseoldclaude.common.Positions;
import com.wiseoldclaude.model.GroundItems;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;

/**
 * Adapter that reads the items on every loaded scene tile into a {@link GroundItems} index. Kept free of
 * logic beyond mapping and price lookup; grouping and capping are decided by {@link GroundItemIndex}. Reads
 * each item's ownership code, never who dropped it. Must be called on the client thread: item definitions
 * are only safe to read there.
 */
public class GroundItemsCollector
{
	/**
	 * A busy scene (a popular boss, the Grand Exchange) holds an estimated few hundred stacks; this keeps all
	 * of them while bounding a pathological scene's file to a few tens of kilobytes.
	 */
	static final int MAX_STACKS = 500;

	private final Client client;
	private final ItemManager itemManager;
	private final GroundItemIndex index = new GroundItemIndex(MAX_STACKS);

	@Inject
	public GroundItemsCollector(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/**
	 * Indexes the ground items around the logged-in character.
	 *
	 * @return the index, or null while no player or scene is loaded (login screen, hopping)
	 */
	public GroundItems collect()
	{
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (player == null || player.getName() == null || view == null)
		{
			return null;
		}

		WorldPoint origin = player.getWorldLocation();
		IndexedGroundItems indexed = index.index(origin, sightingsIn(view.getScene()));
		return GroundItems.builder()
			.rsn(player.getName())
			.capturedAt(Instant.now().toString())
			.world(client.getWorld())
			.instance(view.isInstance())
			.origin(Positions.of(origin))
			.truncated(indexed.isTruncated())
			.items(indexed.getItems())
			.build();
	}

	private List<GroundItemSighting> sightingsIn(Scene scene)
	{
		List<GroundItemSighting> sightings = new ArrayList<>();
		SceneTiles.forEach(scene, tile -> addItemsOn(tile, sightings));
		return sightings;
	}

	/**
	 * Treats a missing ground-item list like an empty one: the API does not promise a non-null list, and a
	 * scene has thousands of tiles without items.
	 */
	private void addItemsOn(Tile tile, List<GroundItemSighting> sightings)
	{
		if (tile == null || tile.getGroundItems() == null)
		{
			return;
		}
		for (TileItem item : tile.getGroundItems())
		{
			sightings.add(sightingOf(item, tile.getWorldLocation()));
		}
	}

	/**
	 * Prices the item the way RuneLite's Ground Items plugin does: the Grand Exchange guide price from
	 * {@link ItemManager#getItemPrice}, which already resolves noted items, coins and platinum tokens, and the
	 * high alchemy value from the item's own definition.
	 */
	private GroundItemSighting sightingOf(TileItem item, WorldPoint tile)
	{
		ItemComposition composition = itemManager.getItemComposition(item.getId());
		return new GroundItemSighting(item.getId(), composition.getName(), item.getQuantity(), item.getOwnership(),
			itemManager.getItemPrice(item.getId()), composition.getHaPrice(), tile);
	}
}

package com.wiseoldclaude.nearby;

import com.wiseoldclaude.common.GameNames;
import com.wiseoldclaude.model.NpcVariant;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/**
 * Reduces the NPCs around the player to what a player could be guided to: named NPCs the client lets them
 * click with at least one option (Attack, Talk-to, Cage, Bank), grouped by name and then by id. Ambient
 * NPCs that offer nothing are dropped for the same reason Examine-only scenery is dropped from the object
 * index: nobody walks to them.
 */
public class NearbyNpcIndex
{
	private final int maxNpcs;

	/**
	 * @param maxNpcs most NPCs to keep; past it only the ones nearest the origin survive, so a crowded scene
	 *   cannot grow the file without bound while the nearest matches, the ones asked for, remain
	 */
	public NearbyNpcIndex(int maxNpcs)
	{
		this.maxNpcs = maxNpcs;
	}

	/**
	 * Builds the index from every NPC the client lists.
	 *
	 * @param origin the player's tile, which defines "nearest" for ordering and the cap
	 * @param sightings every NPC in the scene
	 * @return NPC name, alphabetically, to its variants; variants and their tiles nearest first
	 */
	public IndexedNpcs index(WorldPoint origin, Collection<NpcSighting> sightings)
	{
		List<NpcSighting> ranked = sightings.stream()
			.filter(NearbyNpcIndex::isGuidable)
			.sorted(SceneRanking.nearestFirst(origin))
			.collect(Collectors.toList());

		Map<String, Map<Integer, VariantTiles>> grouped = new TreeMap<>();
		for (NpcSighting sighting : SceneRanking.keepNearest(ranked, maxNpcs))
		{
			grouped.computeIfAbsent(sighting.getName(), name -> new LinkedHashMap<>())
				.computeIfAbsent(sighting.getId(), id -> new VariantTiles(sighting))
				.add(sighting.getTile());
		}

		Map<String, List<NpcVariant>> npcs = new TreeMap<>();
		grouped.forEach((name, variants) -> npcs.put(name,
			variants.values().stream().map(VariantTiles::toVariant).collect(Collectors.toList())));
		return new IndexedNpcs(npcs, ranked.size() > maxNpcs);
	}

	private static boolean isGuidable(NpcSighting sighting)
	{
		return GameNames.isNamed(sighting.getName()) && sighting.isInteractible() && !compact(sighting.getActions()).isEmpty();
	}

	/**
	 * The client pads NPC options to five slots with nulls and some definitions repeat an option; neither
	 * tells the player anything.
	 */
	private static List<String> compact(String[] actions)
	{
		if (actions == null)
		{
			return new ArrayList<>();
		}
		return new ArrayList<>(Arrays.stream(actions)
			.filter(Objects::nonNull)
			.filter(action -> !action.isEmpty())
			.collect(Collectors.toCollection(LinkedHashSet::new)));
	}

	/**
	 * Collects one variant's tiles while the nearest-first walk visits them, so the first tile is the nearest
	 * and a tile two NPCs share is listed once.
	 */
	private static final class VariantTiles
	{
		private final NpcSighting first;
		private final LinkedHashSet<List<Integer>> tiles = new LinkedHashSet<>();

		private VariantTiles(NpcSighting first)
		{
			this.first = first;
		}

		private void add(WorldPoint tile)
		{
			tiles.add(Arrays.asList(tile.getX(), tile.getY(), tile.getPlane()));
		}

		private NpcVariant toVariant()
		{
			int combatLevel = Math.max(0, first.getCombatLevel());
			return new NpcVariant(first.getId(), combatLevel, compact(first.getActions()), new ArrayList<>(tiles));
		}
	}
}

package com.wiseoldclaude.io;

import com.google.gson.Gson;
import java.io.IOException;
import net.runelite.client.util.Filepath;

/**
 * Writes one JSON file per character into the plugin's directory or one of its subdirectories. Writes go to a
 * sibling temp file followed by an atomic rename, so the MCP server never reads a half-written file. Whether null
 * fields are written is each file format's choice, so it is named where the writer is made.
 */
public final class CharacterFileWriter
{
	private final Gson gson;
	private final OutputDirectory directory;
	private final String subdirectory;

	private CharacterFileWriter(Gson gson, OutputDirectory directory, String subdirectory)
	{
		this.gson = gson;
		this.directory = directory;
		this.subdirectory = subdirectory;
	}

	/**
	 * For formats that require optional fields to be present as an explicit null, which Gson omits by default.
	 *
	 * @param gson the client's shared Gson, from which a null-serializing copy is derived
	 * @param directory where the plugin's files go
	 * @return a writer into the plugin's directory itself
	 */
	public static CharacterFileWriter writingNulls(Gson gson, OutputDirectory directory)
	{
		return new CharacterFileWriter(gson.newBuilder().serializeNulls().create(), directory, null);
	}

	/**
	 * For formats whose optional fields are left out when unknown, so a file holding many kinds of entries does not
	 * carry a null for every field another kind uses.
	 *
	 * @param gson the client's shared Gson, used as is
	 * @param directory where the plugin's files go
	 * @return a writer into the plugin's directory itself
	 */
	public static CharacterFileWriter omittingNulls(Gson gson, OutputDirectory directory)
	{
		return new CharacterFileWriter(gson, directory, null);
	}

	/**
	 * A subdirectory keeps the MCP server's listing of {@code *.json} character snapshots from mistaking another
	 * file for a character.
	 *
	 * @param name the subdirectory's name
	 * @return the same writer, writing into that subdirectory
	 */
	public CharacterFileWriter in(String name)
	{
		return new CharacterFileWriter(gson, directory, name);
	}

	/**
	 * Writes a character's file, replacing any previous one.
	 *
	 * @param rsn the character the file belongs to
	 * @param content the value to serialize
	 * @return the written file
	 * @throws IOException if the directory cannot be created or the file cannot be written
	 */
	public Filepath write(String rsn, Object content) throws IOException
	{
		Filepath target = pathFor(rsn);
		AtomicFiles.replace(target, gson.toJson(content));
		return target;
	}

	/**
	 * @param rsn character name
	 * @return where that character's file lives, which may not exist yet
	 * @throws IOException if the plugin's directory cannot be prepared
	 */
	public Filepath pathFor(String rsn) throws IOException
	{
		Filepath root = directory.get();
		return CharacterFiles.pathFor(rsn, subdirectory == null ? root : root.joinSegment(subdirectory));
	}
}

package com.wiseoldclaude.io;

import java.util.Locale;
import java.util.regex.Pattern;
import net.runelite.client.util.Filepath;

/** Names the per-character files every writer and reader shares. */
public final class CharacterFiles
{
	private static final Pattern WINDOWS_DEVICE_NAME = Pattern.compile("con|prn|aux|nul|com[1-9]|lpt[1-9]");

	private CharacterFiles()
	{
	}

	/**
	 * Resolves where a character's file lives in a directory. Shared by every writer and reader so reading back
	 * can never disagree with writing about the file name. Names Windows reserves for devices (a character
	 * called "Con") get a trailing underscore, since {@link Filepath} refuses them on every platform.
	 *
	 * @param rsn character name
	 * @param directory the directory holding one file per character
	 * @return the character's file, which may not exist yet
	 */
	public static Filepath pathFor(String rsn, Filepath directory)
	{
		String stem = rsn.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_-]", "_");
		if (WINDOWS_DEVICE_NAME.matcher(stem).matches())
		{
			stem += "_";
		}
		return directory.joinSegment(stem + ".json");
	}
}

package com.wiseoldclaude.io;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardCopyOption;
import net.runelite.client.util.Filepath;

/**
 * File access for everything the plugin shares with the MCP server, through RuneLite's {@link Filepath} as the
 * Plugin Hub requires. Replacing goes through a sibling temp file followed by an atomic rename, so the server
 * never reads a half-written file while the client is mid-write.
 */
public final class AtomicFiles
{
	private AtomicFiles()
	{
	}

	/**
	 * Writes the content to the target, replacing any previous file, and creates missing parent directories.
	 *
	 * @param target the file to replace
	 * @param content UTF-8 text to write
	 * @throws IOException if the directory cannot be created or the file cannot be written
	 */
	public static void replace(Filepath target, String content) throws IOException
	{
		Filepath directory = target.getParent();
		directory.createDirectories();
		Filepath temp = directory.createTempFile(".write-", ".tmp");
		try
		{
			temp.write(content);
			temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
		}
		finally
		{
			temp.deleteIfExists();
		}
	}

	/**
	 * @param file the file to read
	 * @return its content as UTF-8 text
	 * @throws IOException if it does not exist or cannot be read
	 */
	public static String read(Filepath file) throws IOException
	{
		try (InputStream in = file.openInputStream())
		{
			return new String(in.readAllBytes(), StandardCharsets.UTF_8);
		}
	}
}

package com.wiseoldclaude.io;

import java.io.IOException;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;

/**
 * Moves file writes off the client thread. A failed write is logged and dropped: the next change writes the file
 * again, and an exception must never reach the client's executor.
 */
@Slf4j
public final class BackgroundWrites
{
	/**
	 * One file write.
	 *
	 * @param <T> the value written
	 */
	@FunctionalInterface
	public interface FileWrite<T>
	{
		/**
		 * @param value the value to persist
		 * @throws IOException if the file cannot be written
		 */
		void write(T value) throws IOException;
	}

	private BackgroundWrites()
	{
	}

	/**
	 * @param executor runs the writes, e.g. the client's background executor
	 * @param write persists one value
	 * @param what names the file in the warning a failed write logs
	 * @param <T> the value written
	 * @return a sink that writes each value it accepts on the executor
	 */
	public static <T> Consumer<T> on(Executor executor, FileWrite<T> write, String what)
	{
		return value -> executor.execute(() -> writeLogged(write, value, what));
	}

	private static <T> void writeLogged(FileWrite<T> write, T value, String what)
	{
		try
		{
			write.write(value);
		}
		catch (IOException e)
		{
			log.warn("Failed to write wise-old-claude {}", what, e);
		}
	}
}

package com.wiseoldclaude.io;

import java.io.IOException;
import net.runelite.client.util.Filepath;

/**
 * The plugin's data directory, {@code ~/.runelite/plugin-data/wise-old-claude/}: every file the MCP server reads
 * is written under it, and the guidance request it writes is read from it. Resolved on first use rather than at
 * injection, because RuneLite injects every installed plugin when the client starts, and resolving moves the
 * pre-Filepath {@code ~/.runelite/wise-old-claude/} folder into place, which must only happen once the plugin runs.
 */
public class OutputDirectory
{
	/**
	 * Produces the directory; in the client this is {@code Plugin.getPluginDirectory()}.
	 */
	public interface Source
	{
		/**
		 * @return the directory, which may not exist yet
		 * @throws IOException if the plugin data folder cannot be prepared
		 */
		Filepath resolve() throws IOException;
	}

	private final Source source;
	private Filepath resolved;

	/**
	 * @param source resolves the directory; called at most once successfully
	 */
	public OutputDirectory(Source source)
	{
		this.source = source;
	}

	/**
	 * Synchronized because writers call it from the executor while the client thread reads guidance.
	 *
	 * @return the directory, which may not exist yet
	 * @throws IOException if it cannot be resolved; the next call tries again
	 */
	public synchronized Filepath get() throws IOException
	{
		if (resolved == null)
		{
			resolved = source.resolve();
		}
		return resolved;
	}
}

