/**
 * Exports a read-only snapshot of the logged-in character to {@code ~/.runelite/plugin-data/wise-old-claude/} for
 * the wise-old-claude MCP server, and draws the guidance the server requests there. It never sends input or moves
 * the player: guidance is only a drawn route and hint arrow the player chooses to follow.
 */
@PluginDescriptor(
	name = "Wise Old Claude",
	description = "Exports a snapshot of your character for the wise-old-claude assistant and draws the routes it suggests",
	tags = {"claude", "assistant", "export", "snapshot"},
	internalName = "wise-old-claude",
	legacyDataDirectory = "wise-old-claude"
)
public class WiseOldClaudePlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private WiseOldClaudeConfig config;

	@Inject
	private SnapshotCollector collector;

	@Inject
	private SnapshotWriter writer;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientGuidanceDisplay guidanceDisplay;

	@Inject
	private NearbyObjectRefresh objectRefresh;

	@Inject
	private NearbyNpcRefresh npcRefresh;

	@Inject
	private GroundItemRefresh groundItemRefresh;

	@Inject
	private GameContextRefresh gameContext;

	@Inject
	private QuestProgressRefresh questProgress;

	@Inject
	private QuestStateReader questStateReader;

	@Inject
	private OutputDirectory outputDirectory;

	@Inject
	private PreviousSnapshotReader previousSnapshots;

	private SnapshotSchedule snapshotSchedule;
	private WorldPoint lastPosition;
	private QuestStateRefresh questStates;
	private SnapshotAssembler snapshots;
	private Consumer<PlayerSnapshot> snapshotSink;
	private GuidanceRefresh guidance;

	@Override
	protected void startUp() throws IOException
	{
		applyConfig();
		questStates = new QuestStateRefresh(questStateReader, questProgress::onQuestStates);
		snapshotSink = BackgroundWrites.on(executor, writer::write, "snapshot");
		snapshots = new SnapshotAssembler(previousSnapshots, client::getVarpValue);
		guidance = GuidanceRefresh.in(outputDirectory.get(), guidanceDisplay);
		objectRefresh.markDirty();
	}

	@Override
	protected void shutDown()
	{
		GuidanceRefresh stopping = guidance;
		clientThread.invoke(stopping::stop);
	}

	private void applyConfig()
	{
		snapshotSchedule = new SnapshotSchedule(config.writeIntervalTicks());
		lastPosition = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (WiseOldClaudeConfig.GROUP.equals(event.getGroup()))
		{
			applyConfig();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			snapshotSchedule.markDirty();
			objectRefresh.markDirty();
			questStates.onLogin();
		}
		else if (state == GameState.LOGGING_IN)
		{
			snapshots.onLogin();
		}
		else if (state == GameState.HOPPING)
		{
			snapshots.onHop();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		objectRefresh.markDirty();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			rememberBank(event.getItemContainer());
		}
		if (id == InventoryID.INV || id == InventoryID.WORN || id == InventoryID.BANK)
		{
			snapshotSchedule.markDirty();
		}
	}

	private void rememberBank(ItemContainer container)
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null || container == null)
		{
			return;
		}
		snapshots.rememberBank(player.getName(), collector.bankOf(container));
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		snapshotSchedule.markDirty();
	}

	/**
	 * Writes soon after the player picks or drops a target, so "what am I fighting?" is answered from the fight
	 * in progress and a finished fight stops being reported.
	 */
	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		if (event.getSource() == client.getLocalPlayer())
		{
			snapshotSchedule.markDirty();
		}
	}

	/**
	 * Keeps the target's health current. Only hits on the player or the player's target count, so other fights
	 * nearby do not cause writes.
	 */
	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player player = client.getLocalPlayer();
		Actor hit = event.getActor();
		if (player != null && (hit == player || hit == player.getInteracting()))
		{
			snapshotSchedule.markDirty();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (BirdhouseTracker.watches(event.getVarpId()))
		{
			observeBirdhouses();
		}
		if (CombatVarWatch.affectsSnapshot(event.getVarpId(), event.getVarbitId())
			|| ProgressVarWatch.affectsSnapshot(event.getVarpId(), event.getVarbitId())
			|| BirdhouseTracker.watches(event.getVarpId()))
		{
			snapshotSchedule.markDirty();
		}
	}

	/**
	 * Offers arrive at login and change as they trade.
	 */
	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		snapshotSchedule.markDirty();
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		groundItemRefresh.markDirty();
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		groundItemRefresh.markDirty();
	}

	@Subscribe
	public void onItemQuantityChanged(ItemQuantityChanged event)
	{
		groundItemRefresh.markDirty();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		gameContext.onChatMessage(event);
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		snapshots.onTick();
		followGuidance();
		markDirtyIfMoved();
		refreshQuestsIfDue();
		objectRefresh.onTick(client.getTickCount());
		npcRefresh.onTick(client.getTickCount());
		groundItemRefresh.onTick(client.getTickCount());
		gameContext.onTick(client.getTickCount());
		questProgress.onTick();
		if (!snapshotSchedule.isDue(client.getTickCount()))
		{
			return;
		}
		PlayerSnapshot live = collector.collect();
		if (live == null)
		{
			return;
		}
		PlayerSnapshot snapshot = snapshots.complete(live, questStates.summary());
		snapshotSink.accept(snapshot);
	}

	private void observeBirdhouses()
	{
		Player player = client.getLocalPlayer();
		if (player != null && player.getName() != null)
		{
			snapshots.observeBirdhouses(player.getName(), Positions.of(player.getWorldLocation()));
		}
	}

	private void refreshQuestsIfDue()
	{
		if (questStates.onTick())
		{
			snapshotSchedule.markDirty();
		}
	}

	private void followGuidance()
	{
		Player player = client.getLocalPlayer();
		guidance.onTick(player == null ? null : player.getWorldLocation());
	}

	private void markDirtyIfMoved()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		WorldPoint position = player.getWorldLocation();
		if (!position.equals(lastPosition))
		{
			lastPosition = position;
			snapshotSchedule.markDirty();
		}
	}

	/**
	 * Shares one directory between the plugin and every writer, resolved through {@link #getPluginDirectory()}
	 * on first use; see {@link OutputDirectory} for why not at injection.
	 */
	@Provides
	@Singleton
	OutputDirectory provideOutputDirectory()
	{
		return new OutputDirectory(this::getPluginDirectory);
	}

	@Provides
	WiseOldClaudeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WiseOldClaudeConfig.class);
	}
}

package com.wiseoldclaude.context;

import com.wiseoldclaude.common.JagexMarkup;
import com.wiseoldclaude.model.ItemStack;
import com.wiseoldclaude.model.OpenInterface;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Adapter that reads which tracked interface the player has open from the client's widgets. Kept free of
 * logic beyond reading; cleaning is {@link OpenInterfaces}'. A shop is read from its widget rather than its
 * item container because every shop has its own container id, while the shop interface is always the same.
 * Must be called on the client thread, where widgets and item definitions are safe to read.
 */
public class OpenInterfaceReader
{
	private final Client client;

	@Inject
	public OpenInterfaceReader(Client client)
	{
		this.client = client;
	}

	/**
	 * Checks the main-screen interfaces before the chatbox, since a dialogue can sit under a shop or bank that
	 * is the player's focus.
	 *
	 * @return the open interface, or null when none of the tracked ones is open
	 */
	public OpenInterface read()
	{
		if (isOpen(InterfaceID.Shopmain.UNIVERSE))
		{
			return shop();
		}
		if (isOpen(InterfaceID.Bankmain.UNIVERSE))
		{
			return OpenInterfaces.of(OpenInterface.BANK);
		}
		if (isOpen(InterfaceID.GeOffers.UNIVERSE))
		{
			return OpenInterfaces.of(OpenInterface.GRAND_EXCHANGE);
		}
		return dialogue();
	}

	/**
	 * Asks the interface's root layer, as RuneLite's own plugins do; the bank's component 0 is not its root.
	 */
	private boolean isOpen(int rootComponentId)
	{
		return visible(client.getWidget(rootComponentId));
	}

	private OpenInterface shop()
	{
		List<ItemStack> slots = new ArrayList<>();
		for (Widget slot : childrenOf(InterfaceID.Shopmain.ITEMS))
		{
			int itemId = slot.getItemId();
			if (itemId >= 0)
			{
				slots.add(new ItemStack(itemId, client.getItemDefinition(itemId).getName(), slot.getItemQuantity()));
			}
		}
		return OpenInterfaces.shop(shopTitle(), slots);
	}

	/**
	 * The title is drawn as one of the frame's generated children; the first child with text is it.
	 */
	private String shopTitle()
	{
		for (Widget child : childrenOf(InterfaceID.Shopmain.FRAME))
		{
			if (!JagexMarkup.plain(child.getText()).isEmpty())
			{
				return child.getText();
			}
		}
		return null;
	}

	private OpenInterface dialogue()
	{
		Widget npcLine = client.getWidget(InterfaceID.ChatLeft.TEXT);
		if (visible(npcLine))
		{
			return OpenInterfaces.dialogue(textOf(InterfaceID.ChatLeft.NAME), npcLine.getText());
		}
		Widget playerLine = client.getWidget(InterfaceID.ChatRight.TEXT);
		if (visible(playerLine))
		{
			return OpenInterfaces.dialogue(textOf(InterfaceID.ChatRight.NAME), playerLine.getText());
		}
		if (visible(client.getWidget(InterfaceID.Chatmenu.OPTIONS)))
		{
			List<String> lines = new ArrayList<>();
			childrenOf(InterfaceID.Chatmenu.OPTIONS).forEach(option -> lines.add(option.getText()));
			return OpenInterfaces.choice(lines);
		}
		return messageBox();
	}

	private OpenInterface messageBox()
	{
		for (int textId : new int[]{InterfaceID.Messagebox.TEXT, InterfaceID.Objectbox.TEXT})
		{
			Widget box = client.getWidget(textId);
			if (visible(box))
			{
				return OpenInterfaces.dialogue(null, box.getText());
			}
		}
		return null;
	}

	private String textOf(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		return widget == null ? null : widget.getText();
	}

	private List<Widget> childrenOf(int componentId)
	{
		List<Widget> children = new ArrayList<>();
		Widget parent = client.getWidget(componentId);
		Widget[] generated = parent == null ? null : parent.getChildren();
		if (generated == null)
		{
			return children;
		}
		for (Widget child : generated)
		{
			if (child != null)
			{
				children.add(child);
			}
		}
		return children;
	}

	private static boolean visible(Widget widget)
	{
		return widget != null && !widget.isHidden();
	}
}

package com.wiseoldclaude.context;

import com.wiseoldclaude.common.JagexMarkup;
import com.wiseoldclaude.model.GameMessage;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.EnumSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import net.runelite.api.ChatMessageType;

/**
 * The player's recent game feed: what the game told them ("You need an axe to chop down this tree."), what
 * NPCs said to them, and what they examined. An allow-list rather than a block-list, so a chat type Jagex adds
 * later stays out until someone decides it is the player's own; other players' chat (public, private,
 * friends, clan, trade, broadcasts) is never kept.
 */
class GameMessageLog
{
	/**
	 * The game's own feed: the types RuneLite's chat filter treats as game messages, filtered game spam (where
	 * most skilling lines land once the in-game filter is on), RuneLite's own notices, the player's dialogue
	 * with NPCs and message boxes, and the player's examines.
	 */
	private static final Set<ChatMessageType> OWN_TYPES = EnumSet.of(
		ChatMessageType.GAMEMESSAGE,
		ChatMessageType.ENGINE,
		ChatMessageType.SPAM,
		ChatMessageType.CONSOLE,
		ChatMessageType.DIALOG,
		ChatMessageType.MESBOX,
		ChatMessageType.ITEM_EXAMINE,
		ChatMessageType.NPC_EXAMINE,
		ChatMessageType.OBJECT_EXAMINE);

	/**
	 * Separates the speaker from the line in a dialogue message, as RuneLite's clue scroll plugin reads them.
	 */
	private static final String DIALOGUE_SEPARATOR = "|";

	private final int capacity;
	private final Deque<GameMessage> messages = new ArrayDeque<>();

	/**
	 * @param capacity how many distinct messages to remember before forgetting the oldest
	 */
	GameMessageLog(int capacity)
	{
		this.capacity = capacity;
	}

	/**
	 * Keeps the message if it belongs to the player's own feed.
	 *
	 * @param type the chat channel the message arrived on
	 * @param message the raw, tagged message text
	 * @param at when it arrived
	 * @return true when the log changed
	 */
	boolean record(ChatMessageType type, String message, Instant at)
	{
		if (!OWN_TYPES.contains(type))
		{
			return false;
		}
		GameMessage parsed = parse(type, message, at.toString());
		if (parsed.getText().isEmpty())
		{
			return false;
		}
		GameMessage previous = messages.peekLast();
		if (previous != null && sameLine(previous, parsed))
		{
			messages.removeLast();
			messages.addLast(previous.repeatedAt(parsed.getAt()));
			return true;
		}
		messages.addLast(parsed);
		if (messages.size() > capacity)
		{
			messages.removeFirst();
		}
		return true;
	}

	/**
	 * @return the remembered messages, oldest first, as a copy safe to hand to another thread
	 */
	List<GameMessage> messages()
	{
		return new ArrayList<>(messages);
	}

	/**
	 * Forgets every message, for when a different character logs in.
	 */
	void clear()
	{
		messages.clear();
	}

	private static GameMessage parse(ChatMessageType type, String message, String at)
	{
		int separator = message == null ? -1 : message.indexOf(DIALOGUE_SEPARATOR);
		if (type != ChatMessageType.DIALOG || separator < 0)
		{
			return new GameMessage(at, null, JagexMarkup.plain(message), 1);
		}
		String speaker = JagexMarkup.plain(message.substring(0, separator));
		String line = JagexMarkup.plain(message.substring(separator + 1));
		return new GameMessage(at, speaker.isEmpty() ? null : speaker, line, 1);
	}

	private static boolean sameLine(GameMessage a, GameMessage b)
	{
		return a.getText().equals(b.getText()) && Objects.equals(a.getSpeaker(), b.getSpeaker());
	}
}

package com.wiseoldclaude.context;

import com.wiseoldclaude.common.LocalPlayer;
import com.wiseoldclaude.common.WriteThrottle;
import com.wiseoldclaude.io.BackgroundWrites;
import com.wiseoldclaude.model.GameContext;
import com.wiseoldclaude.model.OpenInterface;
import java.time.Instant;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;

/**
 * Keeps the game-context file current: the player's own recent game messages and the interface they have
 * open. Messages are pushed by {@link #onChatMessage}; the open interface has no single event and is polled
 * each tick, which costs a handful of widget lookups. Both calls arrive on the client thread, so no locking is
 * needed; only an immutable context crosses to the executor for the write.
 */
public class GameContextRefresh
{
	/**
	 * At most one write every 1.2 seconds: a burst of messages (a level-up, a drop, a full inventory) lands in
	 * one write, and the assistant reads the file seconds later anyway.
	 */
	static final int WRITE_INTERVAL_TICKS = 2;

	/**
	 * While an interface is open the file is rewritten every 30 seconds even when nothing changed. A closed
	 * client or a logout writes nothing more, so without this a shop open at that moment would read as open
	 * forever; the server treats an open interface in a file older than this as unknown.
	 */
	static final int KEEPALIVE_TICKS = 50;

	/**
	 * Enough to cover what just happened (the last minute or so of play) without the file growing past a few
	 * kilobytes.
	 */
	static final int MESSAGE_CAPACITY = 30;

	private final Supplier<String> player;
	private final Supplier<OpenInterface> interfaces;
	private final Consumer<GameContext> sink;
	private final GameMessageLog messages = new GameMessageLog(MESSAGE_CAPACITY);
	private final WriteThrottle throttle = new WriteThrottle(WRITE_INTERVAL_TICKS);
	private String rsn;
	private OpenInterface open;
	private int lastWriteTick = Integer.MIN_VALUE;

	/**
	 * Reads the client and writes into the plugin's output directory off the client thread.
	 *
	 * @param client the game client, for the character's name
	 * @param reader reads the open interface
	 * @param io the writer and the client's background executor, so disk writes never stall a frame
	 */
	@Inject
	public GameContextRefresh(Client client, OpenInterfaceReader reader, ContextIo io)
	{
		this(() -> LocalPlayer.nameOf(client), reader::read, BackgroundWrites.on(io.executor, io.writer::write, "game context"));
	}

	/**
	 * @param player the logged-in character's name, or null while none is loaded
	 * @param interfaces the open interface, or null when none is
	 * @param sink receives each context worth writing
	 */
	GameContextRefresh(Supplier<String> player, Supplier<OpenInterface> interfaces, Consumer<GameContext> sink)
	{
		this.player = player;
		this.interfaces = interfaces;
		this.sink = sink;
	}

	/**
	 * Records a chat message if it is part of the player's own game feed.
	 *
	 * @param event any chat message the client received
	 */
	public void onChatMessage(ChatMessage event)
	{
		record(event.getType(), event.getMessage(), Instant.now());
	}

	/**
	 * The testable core of {@link #onChatMessage}, with the arrival time supplied instead of read from the clock.
	 *
	 * @param type the chat channel
	 * @param message the raw message text
	 * @param at when it arrived
	 */
	void record(ChatMessageType type, String message, Instant at)
	{
		if (messages.record(type, message, at))
		{
			throttle.markDirty();
		}
	}

	/**
	 * Notices interface changes and character switches, and writes when something changed and the interval
	 * has elapsed. A brief unload (world hop, loading screen) keeps the messages; only a different character
	 * clears them, so one account's messages never land in another's file.
	 *
	 * @param tick current game tick count
	 */
	public void onTick(int tick)
	{
		String current = player.get();
		if (current == null)
		{
			return;
		}
		if (!current.equals(rsn))
		{
			if (rsn != null)
			{
				messages.clear();
			}
			rsn = current;
			throttle.markDirty();
		}
		OpenInterface latest = interfaces.get();
		if (!Objects.equals(latest, open))
		{
			open = latest;
			throttle.markDirty();
		}
		if (open != null && tick - lastWriteTick >= KEEPALIVE_TICKS)
		{
			throttle.markDirty();
		}
		if (!throttle.tryAcquire(tick))
		{
			return;
		}
		lastWriteTick = tick;
		sink.accept(GameContext.builder()
			.rsn(rsn)
			.capturedAt(Instant.now().toString())
			.messages(messages.messages())
			.openInterface(open)
			.build());
	}

	/**
	 * Where a context goes once built; grouped so the injected constructor stays within three collaborators.
	 */
	static class ContextIo
	{
		private final GameContextWriter writer;
		private final ScheduledExecutorService executor;

		@Inject
		ContextIo(GameContextWriter writer, ScheduledExecutorService executor)
		{
			this.writer = writer;
			this.executor = executor;
		}
	}
}

package com.wiseoldclaude.context;

import com.wiseoldclaude.common.GameNames;
import com.wiseoldclaude.common.JagexMarkup;
import com.wiseoldclaude.model.ItemStack;
import com.wiseoldclaude.model.OpenInterface;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Builds {@link OpenInterface} values from raw widget text and item slots, cleaning markup and dropping slots
 * that hold no real item. Kept apart from {@link OpenInterfaceReader} so the cleaning is testable without a
 * client.
 */
final class OpenInterfaces
{
	/**
	 * The name the client gives an item definition that does not describe a real item.
	 */

	private OpenInterfaces()
	{
	}

	/**
	 * @param kind {@link OpenInterface#BANK} or {@link OpenInterface#GRAND_EXCHANGE}, whose contents are
	 *   exported elsewhere or not at all
	 * @return an interface that carries only its kind
	 */
	static OpenInterface of(String kind)
	{
		return new OpenInterface(kind, null, null, null, null, null);
	}

	/**
	 * Keeps sold-out items: "they sell it but are out" answers "where can I buy one?" differently from "they
	 * never sell it".
	 *
	 * @param rawTitle the shop title widget's text
	 * @param slots every displayed slot with its resolved item name
	 * @return the shop with its stock in display order
	 */
	static OpenInterface shop(String rawTitle, List<ItemStack> slots)
	{
		List<ItemStack> stock = slots.stream()
			.filter(slot -> slot.getId() >= 0 && GameNames.isNamed(slot.getName()))
			.collect(Collectors.toList());
		return new OpenInterface(OpenInterface.SHOP, orNull(JagexMarkup.plain(rawTitle)), stock, null, null, null);
	}

	/**
	 * @param rawSpeaker the name widget's text, or null for a box without a speaker
	 * @param rawText the dialogue line
	 * @return the line on screen
	 */
	static OpenInterface dialogue(String rawSpeaker, String rawText)
	{
		return new OpenInterface(OpenInterface.DIALOGUE, null, null, orNull(JagexMarkup.plain(rawSpeaker)),
			JagexMarkup.plain(rawText), null);
	}

	/**
	 * The options widget lists its prompt ("Select an Option") first, then each choice; blank and missing
	 * children are padding.
	 *
	 * @param rawLines the options widget's child texts in order
	 * @return the prompt and choices on screen
	 */
	static OpenInterface choice(List<String> rawLines)
	{
		List<String> lines = new ArrayList<>();
		for (String raw : rawLines)
		{
			String line = JagexMarkup.plain(raw);
			if (!line.isEmpty())
			{
				lines.add(line);
			}
		}
		String prompt = lines.isEmpty() ? null : lines.get(0);
		List<String> options = lines.isEmpty() ? lines : lines.subList(1, lines.size());
		return new OpenInterface(OpenInterface.DIALOGUE, null, null, null, prompt, new ArrayList<>(options));
	}

	private static String orNull(String text)
	{
		return text.isEmpty() ? null : text;
	}
}

package com.wiseoldclaude.context;

import com.google.gson.Gson;
import com.wiseoldclaude.io.CharacterFileWriter;
import com.wiseoldclaude.io.OutputDirectory;
import com.wiseoldclaude.model.GameContext;
import java.io.IOException;
import javax.inject.Inject;
import net.runelite.client.util.Filepath;

/**
 * Persists the game context as one file per character under {@code context/}.
 */
public class GameContextWriter
{
	static final String CONTEXT_DIR = "context";

	private final CharacterFileWriter files;

	/**
	 * Leaves nulls out: most fields of a message or an open interface apply to only one kind, and writing them all as
	 * null would double the file for no information. The file format marks those fields optional to match.
	 *
	 * @param gson the client's shared Gson
	 * @param directory where the plugin's files go
	 */
	@Inject
	public GameContextWriter(Gson gson, OutputDirectory directory)
	{
		this.files = CharacterFileWriter.omittingNulls(gson, directory).in(CONTEXT_DIR);
	}

	/**
	 * Writes the file, replacing any previous one for the same character.
	 *
	 * @param context the value to persist
	 * @return the written file
	 * @throws IOException if the directory cannot be created or the file cannot be written
	 */
	public Filepath write(GameContext context) throws IOException
	{
		return files.write(context.getRsn(), context);
	}
}

package com.wiseoldclaude.quests;

import java.util.List;
import lombok.Value;

/**
 * The quest journal interface's text exactly as the client holds it, tags included, so all interpretation
 * stays in {@link QuestJournalParser} where it can be tested without a client.
 */
@Value
class RawQuestJournal
{
	String title;

	/**
	 * One entry per line widget, top to bottom, including blank and unused lines.
	 */
	List<String> lines;
}

package com.wiseoldclaude.quests;

import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Reads quest state from the client. Call on the client thread. */
public class QuestStateReader implements QuestStateSource
{
	private final Client client;

	/**
	 * @param client the game client
	 */
	@Inject
	public QuestStateReader(Client client)
	{
		this.client = client;
	}

	/**
	 * Reads every quest's progress. Each read runs a client script, so this is called on a schedule rather
	 * than on every snapshot.
	 *
	 * @return quest display name to progress, in RuneLite's quest order
	 */
	@Override
	public Map<String, QuestState> quests()
	{
		Map<String, QuestState> quests = new LinkedHashMap<>();
		for (Quest quest : Quest.values())
		{
			quests.put(quest.getName(), quest.getState(client));
		}
		return quests;
	}

	/**
	 * Reads the game's own quest point total (the varp RuneLite's {@code !qp} chat command reports) instead
	 * of summing points per quest, which would need a hand-maintained points table.
	 *
	 * @return total quest points
	 */
	@Override
	public int questPoints()
	{
		return client.getVarpValue(VarPlayerID.QP);
	}

	/**
	 * Reads Fairytale II's state and stage varbit and judges fairy ring access from them via
	 * {@link FairyRingAccess}. Runs a quest-state script, so it is read on the quest schedule.
	 *
	 * @return true when the character has permission to use fairy rings
	 */
	@Override
	public boolean fairyRingsUnlocked()
	{
		return FairyRingAccess.isUnlocked(
			Quest.FAIRYTALE_II__CURE_A_QUEEN.getState(client),
			client.getVarbitValue(VarbitID.FAIRY2_QUEENCURE_QUEST));
	}
}

package com.wiseoldclaude.quests;

import net.runelite.api.QuestState;

/**
 * Decides whether the character may use the fairy ring network, so the assistant stops hedging on fairy ring
 * routes. The OSRS Wiki states rings unlock part-way through Fairytale II - Cure a Queen, once the Fairy
 * Godfather grants permission, but does not document the stage value of the quest's progress varbit
 * ({@code VarbitID.FAIRY2_QUEENCURE_QUEST}, 2326) at which that happens.
 * <p>
 * The threshold is taken from Quest Helper (https://github.com/Zoinkwiz/quest-helper, BSD 2-Clause,
 * Copyright (c) 2020, Zoinkwiz), whose Fairytale II helper marks stage 40 as "Talked to godfather for fairy
 * rings" and whose achievement diary helpers gate fairy ring steps on that varbit being at least 40.
 * <p>
 * Only quest progress is judged: wielding a dramen or lunar staff (or the elite Lumbridge &amp; Draynor diary)
 * is still needed to travel, and that is not captured here.
 */
public final class FairyRingAccess
{
	/**
	 * Fairytale II stage at which the Fairy Godfather has granted permission to use fairy rings.
	 */
	static final int GODFATHER_PERMISSION_STAGE = 40;

	private FairyRingAccess()
	{
	}

	/**
	 * Judges fairy ring access from Fairytale II progress. A finished quest unlocks rings outright, so the stage
	 * varbit is only consulted mid-quest, where its completion value need not be relied on.
	 *
	 * @param fairytaleII the quest's state as the client reports it
	 * @param questStage the value of the quest's progress varbit (2326)
	 * @return true when the character has permission to use fairy rings
	 */
	public static boolean isUnlocked(QuestState fairytaleII, int questStage)
	{
		if (fairytaleII == QuestState.FINISHED)
		{
			return true;
		}
		return fairytaleII == QuestState.IN_PROGRESS && questStage >= GODFATHER_PERMISSION_STAGE;
	}
}

