package com.wiseoldclaude.quests;

import java.util.Map;
import net.runelite.api.QuestState;

/** The client reads behind the quest list, quest points and fairy ring access. */
public interface QuestStateSource
{
	/**
	 * @return quest display name to progress, in RuneLite's quest order
	 */
	Map<String, QuestState> quests();

	/**
	 * @return total quest points
	 */
	int questPoints();

	/**
	 * @return true when the character has permission to use fairy rings
	 */
	boolean fairyRingsUnlocked();
}

package com.wiseoldclaude.quests;

import com.wiseoldclaude.common.JagexMarkup;
import com.wiseoldclaude.model.JournalLine;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Locale;

/**
 * Interprets the quest journal interface's tagged text. The game marks a finished step by drawing its line
 * struck through with a {@code <str>} tag, re-opened on every wrapped line of the step (RuneLite's
 * achievement diary plugin and Quest Helper both test lines for a {@code <str>} prefix), so a line is done
 * exactly when its own text carries the tag.
 */
final class QuestJournalParser
{
	private static final String STRIKE_TAG = "<str>";

	private QuestJournalParser()
	{
	}

	/**
	 * @param rawLines the line widgets' texts top to bottom, nulls and blanks included
	 * @return the readable lines with their finished state, blank lines dropped
	 */
	static List<JournalLine> lines(List<String> rawLines)
	{
		List<JournalLine> lines = new ArrayList<>();
		for (String raw : rawLines)
		{
			String text = JagexMarkup.plain(raw);
			if (!text.isEmpty())
			{
				lines.add(new JournalLine(text, raw.toLowerCase(Locale.ROOT).contains(STRIKE_TAG)));
			}
		}
		return lines;
	}

	/**
	 * Resolves the journal's title to a quest. The interface also shows non-quest scrolls, so a title naming no
	 * known quest is rejected rather than saved under a made-up name. An exact match wins; otherwise the
	 * longest quest name the title contains, so "Dragon Slayer II" is never filed under "Dragon Slayer I".
	 *
	 * @param rawTitle the title widget's tagged text, possibly null
	 * @param questNames every known quest name
	 * @return the matching quest name, or null when the title names no known quest
	 */
	static String questFor(String rawTitle, Collection<String> questNames)
	{
		String title = JagexMarkup.plain(rawTitle).toLowerCase(Locale.ROOT);
		if (title.isEmpty())
		{
			return null;
		}
		String longestContained = null;
		for (String quest : questNames)
		{
			String name = quest.toLowerCase(Locale.ROOT);
			if (name.equals(title))
			{
				return quest;
			}
			if (title.contains(name) && (longestContained == null || quest.length() > longestContained.length()))
			{
				longestContained = quest;
			}
		}
		return longestContained;
	}
}

package com.wiseoldclaude.quests;

import com.wiseoldclaude.model.QuestJournal;
import com.wiseoldclaude.snapshot.BankMemory;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.function.Function;

/**
 * Remembers the last journal seen for each of a character's quests. The game shows a journal only while it is
 * open, so without memory the text would be lost the moment the player closes it, and on every client restart.
 * A character's first lookup is seeded from the previously exported file, like {@link BankMemory}.
 * Not thread-safe: use only from the client thread.
 */
public class QuestJournalMemory
{
	private final Function<String, Map<String, QuestJournal>> previousJournals;
	private final Map<String, Map<String, QuestJournal>> journals = new HashMap<>();

	/**
	 * @param previousJournals loads a character's journals from its previous export, empty when none
	 */
	public QuestJournalMemory(Function<String, Map<String, QuestJournal>> previousJournals)
	{
		this.previousJournals = previousJournals;
	}

	/**
	 * Records a journal as just read. A reopened journal with the same text and stage keeps its original
	 * capture time, so the assistant can tell how long the player has been at that step.
	 *
	 * @param rsn character the journal belongs to
	 * @param quest quest name
	 * @param journal the journal as just read
	 * @return true when the text or stage differs from what was remembered, meaning the export needs rewriting
	 */
	public boolean record(String rsn, String quest, QuestJournal journal)
	{
		Map<String, QuestJournal> known = journalsOf(rsn);
		QuestJournal previous = known.get(quest);
		if (previous != null && sameContent(previous, journal))
		{
			return false;
		}
		known.put(quest, journal);
		return true;
	}

	/**
	 * @param rsn character to look up
	 * @return the character's journals by quest name, alphabetically; empty when none was ever seen
	 */
	public Map<String, QuestJournal> journalsFor(String rsn)
	{
		return Collections.unmodifiableMap(new TreeMap<>(journalsOf(rsn)));
	}

	private Map<String, QuestJournal> journalsOf(String rsn)
	{
		return journals.computeIfAbsent(rsn, name -> new HashMap<>(previousJournals.apply(name)));
	}

	private static boolean sameContent(QuestJournal a, QuestJournal b)
	{
		return Objects.equals(a.getLines(), b.getLines()) && Objects.equals(a.getStageAtCapture(), b.getStageAtCapture());
	}
}

package com.wiseoldclaude.quests;

import com.wiseoldclaude.common.LocalPlayer;
import com.wiseoldclaude.io.BackgroundWrites;
import com.wiseoldclaude.model.JournalLine;
import com.wiseoldclaude.model.QuestJournal;
import com.wiseoldclaude.model.QuestProgress;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;

/**
 * Keeps the quest-progress file current. The journal's text can be filled in after the interface loads and
 * changes without an event of its own, so it is polled each tick: one widget lookup while it is closed, and a
 * capture only once the text differs from what is remembered. Stages are fed in from the plugin's existing quest refresh, since knowing which quests
 * are in progress already costs a script run per quest there. Both calls arrive on the client thread; only an
 * immutable progress value crosses to the executor for the write.
 */
public class QuestProgressRefresh
{
	private static final List<String> QUEST_NAMES = questNames();

	private final Sources sources;
	private final QuestJournalMemory memory;
	private final Consumer<QuestProgress> sink;
	private String rsn;
	private Map<String, Integer> stages;
	private boolean dirty;

	/**
	 * Reads the client and writes into the plugin's output directory off the client thread.
	 *
	 * @param client the game client, for the character's name and quest variables
	 * @param reader reads the open quest journal
	 * @param io the writer, the previous file's reader and the client's background executor
	 */
	@Inject
	public QuestProgressRefresh(Client client, QuestJournalReader reader, ProgressIo io)
	{
		this(new Sources(() -> LocalPlayer.nameOf(client), reader::read, new ClientQuestVars(client), Instant::now),
			new QuestJournalMemory(io.previous::lastJournals),
			BackgroundWrites.on(io.executor, io.writer::write, "quest progress"));
	}

	/**
	 * @param sources what the refresh reads
	 * @param memory remembers journals per character across closes and restarts
	 * @param sink receives each progress worth writing
	 */
	QuestProgressRefresh(Sources sources, QuestJournalMemory memory, Consumer<QuestProgress> sink)
	{
		this.sources = sources;
		this.memory = memory;
		this.sink = sink;
	}

	/**
	 * Captures the open journal if its text or the quest's stage differs from what is remembered, and writes
	 * when anything changed.
	 */
	public void onTick()
	{
		String current = currentCharacter();
		if (current == null)
		{
			return;
		}
		captureOpenJournal(current);
		if (dirty)
		{
			dirty = false;
			sink.accept(QuestProgress.builder()
				.rsn(current)
				.capturedAt(sources.clock.get().toString())
				.stages(stages)
				.journals(memory.journalsFor(current))
				.build());
		}
	}

	/**
	 * Re-reads the stages of in-progress quests after the plugin has read quest states.
	 *
	 * @param states every quest's state by name, in RuneLite's quest order
	 */
	public void onQuestStates(Map<String, QuestState> states)
	{
		if (currentCharacter() == null)
		{
			return;
		}
		Map<String, Integer> latest = Collections.unmodifiableMap(QuestStageTable.inProgressStages(states, sources.vars));
		if (!latest.equals(stages))
		{
			stages = latest;
			dirty = true;
		}
	}

	/**
	 * Follows character switches. Stages belong to the character they were read for, so a new character has
	 * none until its quests are read.
	 */
	private String currentCharacter()
	{
		String current = sources.player.get();
		if (current != null && !current.equals(rsn))
		{
			rsn = current;
			stages = null;
		}
		return current;
	}

	private void captureOpenJournal(String character)
	{
		RawQuestJournal open = sources.journal.get();
		if (open == null)
		{
			return;
		}
		String quest = QuestJournalParser.questFor(open.getTitle(), QUEST_NAMES);
		List<JournalLine> lines = QuestJournalParser.lines(open.getLines());
		if (quest == null || lines.isEmpty())
		{
			return;
		}
		QuestJournal journal = QuestJournal.builder()
			.capturedAt(sources.clock.get().toString())
			.stageAtCapture(QuestStageTable.stageOf(quest, sources.vars))
			.lines(lines)
			.build();
		if (memory.record(character, quest, journal))
		{
			dirty = true;
		}
	}

	private static List<String> questNames()
	{
		List<String> names = new ArrayList<>();
		for (Quest quest : Quest.values())
		{
			names.add(quest.getName());
		}
		return Collections.unmodifiableList(names);
	}

	/**
	 * What the refresh reads, grouped so the constructor stays within three collaborators.
	 */
	static class Sources
	{
		private final Supplier<String> player;
		private final Supplier<RawQuestJournal> journal;
		private final QuestVars vars;
		private final Supplier<Instant> clock;

		/**
		 * @param player the logged-in character's name, or null while none is loaded
		 * @param journal the open quest journal, or null when it is closed
		 * @param vars reads quest progress variables
		 * @param clock the current time, for capture stamps
		 */
		Sources(Supplier<String> player, Supplier<RawQuestJournal> journal, QuestVars vars, Supplier<Instant> clock)
		{
			this.player = player;
			this.journal = journal;
			this.vars = vars;
			this.clock = clock;
		}
	}

	/**
	 * Where progress goes once built and where remembered journals come from; grouped so the injected
	 * constructor stays within three collaborators.
	 */
	static class ProgressIo
	{
		private final QuestProgressWriter writer;
		private final PreviousQuestProgressReader previous;
		private final ScheduledExecutorService executor;

		@Inject
		ProgressIo(QuestProgressWriter writer, PreviousQuestProgressReader previous, ScheduledExecutorService executor)
		{
			this.writer = writer;
			this.previous = previous;
			this.executor = executor;
		}
	}

	/**
	 * Reads quest variables straight from the client, as Quest Helper's {@code QuestHelperQuest.getVar} does.
	 */
	private static class ClientQuestVars implements QuestVars
	{
		private final Client client;

		ClientQuestVars(Client client)
		{
			this.client = client;
		}

		@Override
		public int varbit(int id)
		{
			return client.getVarbitValue(id);
		}

		@Override
		public int varp(int id)
		{
			return client.getVarpValue(id);
		}
	}
}

package com.wiseoldclaude.quests;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import com.wiseoldclaude.io.AtomicFiles;
import com.wiseoldclaude.io.OutputDirectory;
import com.wiseoldclaude.model.QuestJournal;
import com.wiseoldclaude.model.QuestProgress;
import java.io.IOException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;

/**
 * Recovers the journals a character's previous quest-progress file recorded, so journals read in an earlier
 * session survive a client restart. An unreadable or incomplete file yields "nothing known" rather than an
 * error: losing an old journal is preferable to failing the export.
 */
public class PreviousQuestProgressReader
{
	private final Gson gson;
	private final OutputDirectory directory;

	/**
	 * @param gson deserializer matching the one the files were written with
	 * @param directory the plugin's data directory {@link QuestProgressWriter} writes under
	 */
	@Inject
	public PreviousQuestProgressReader(Gson gson, OutputDirectory directory)
	{
		this.gson = gson;
		this.directory = directory;
	}

	/**
	 * @param rsn character whose previous file to read
	 * @return the complete journals recorded there by quest name; empty when there is none or it cannot be read
	 */
	public Map<String, QuestJournal> lastJournals(String rsn)
	{
		try
		{
			String json = AtomicFiles.read(QuestProgressWriter.pathFor(rsn, directory.get()));
			QuestProgress previous = gson.fromJson(new JsonParser().parse(json), QuestProgress.class);
			return previous == null || previous.getJournals() == null ? Collections.emptyMap() : complete(previous.getJournals());
		}
		catch (IOException | JsonParseException | IllegalStateException e)
		{
			return Collections.emptyMap();
		}
	}

	private static Map<String, QuestJournal> complete(Map<String, QuestJournal> journals)
	{
		Map<String, QuestJournal> complete = new HashMap<>();
		journals.forEach((quest, journal) ->
		{
			if (journal != null && journal.getCapturedAt() != null && journal.getLines() != null)
			{
				complete.put(quest, journal);
			}
		});
		return complete;
	}
}

package com.wiseoldclaude.quests;

/**
 * Decides when to re-read quest states. Reading one quest runs a client script, so all ~200 quests are
 * read on a fixed cadence instead of on every snapshot write. Quest progress changes on a scale of
 * minutes, so a refresh on the first tick after login plus one per interval keeps the export fresh enough.
 * Counts ticks itself rather than comparing client tick counts, so it does not depend on whether the
 * client's tick counter survives a login.
 */
public class QuestRefreshSchedule
{
	private final int intervalTicks;
	private int ticksUntilDue;

	/**
	 * Starts armed, so a plugin enabled mid-session reads quests on its first tick.
	 *
	 * @param intervalTicks game ticks between periodic refreshes
	 */
	public QuestRefreshSchedule(int intervalTicks)
	{
		this.intervalTicks = intervalTicks;
		onLogin();
	}

	/**
	 * Requests a refresh on the next tick. Quest varps are only trustworthy once the game has ticked
	 * after login, so the read is deferred to the tick rather than done in the login event itself.
	 */
	public void onLogin()
	{
		ticksUntilDue = 1;
	}

	/**
	 * Advances one game tick.
	 *
	 * @return true when quests should be read on this tick
	 */
	public boolean onTick()
	{
		ticksUntilDue--;
		if (ticksUntilDue > 0)
		{
			return false;
		}
		ticksUntilDue = intervalTicks;
		return true;
	}
}

