package com.wiseoldclaude.quests;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;

/**
 * Adapter that reads the open quest journal (interface {@code questjournal}, group 119) from the client's
 * widgets. The title sits in {@link InterfaceID.Questjournal#TITLE}; each drawn line is one of the static
 * components {@code QJ1}..{@code QJ210} under {@link InterfaceID.Questjournal#TEXTLAYER}, which is where Quest
 * Helper's journal checks look for text too. Text is macro-expanded as Quest Helper does, so shorthand colour
 * and strike macros become the tags the parser understands. Must be called on the client thread.
 */
@Slf4j
public class QuestJournalReader
{
	private final Client client;
	private String lastLoggedTitle;

	@Inject
	public QuestJournalReader(Client client)
	{
		this.client = client;
	}

	/**
	 * @return the open journal's raw title and lines, or null when the quest journal is not open
	 */
	public RawQuestJournal read()
	{
		Widget title = client.getWidget(InterfaceID.Questjournal.TITLE);
		Widget textLayer = client.getWidget(InterfaceID.Questjournal.TEXTLAYER);
		if (title == null || title.isHidden() || textLayer == null)
		{
			return null;
		}
		String titleText = client.macroExpand(title.getText());
		logLayoutOnce(titleText, textLayer);
		return new RawQuestJournal(titleText, visibleLines(textLayer));
	}

	private List<String> visibleLines(Widget textLayer)
	{
		List<String> lines = new ArrayList<>();
		Widget[] children = textLayer.getStaticChildren();
		if (children == null)
		{
			return lines;
		}
		for (Widget line : children)
		{
			if (line != null && !line.isHidden())
			{
				lines.add(client.macroExpand(line.getText()));
			}
		}
		return lines;
	}

	/**
	 * Logs, once per opened journal, how its lines are laid out and which quest the game says was opened last,
	 * so a developer-mode client can confirm the widget layout this reader assumes.
	 */
	private void logLayoutOnce(String titleText, Widget textLayer)
	{
		if (!log.isDebugEnabled() || Objects.equals(titleText, lastLoggedTitle))
		{
			return;
		}
		lastLoggedTitle = titleText;
		log.debug("Quest journal '{}': {} static, {} dynamic line widgets; latest quest journal varp {}",
			titleText, countOf(textLayer.getStaticChildren()), countOf(textLayer.getDynamicChildren()),
			client.getVarpValue(VarPlayerID.LATEST_QUEST_JOURNAL));
	}

	private static int countOf(Widget[] widgets)
	{
		return widgets == null ? 0 : widgets.length;
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.common.WriteThrottle;

/**
 * Decides when the snapshot is written: soon after anything in it changes, but no more often than the configured
 * interval, and at least once a minute while logged in even when nothing changed. The keep-alive lets the MCP server
 * tell an idle player from a client that is not running, since both would otherwise leave the file untouched.
 */
public class SnapshotSchedule
{
	/** One minute, half the age at which the MCP server calls a snapshot stale. */
	static final int KEEPALIVE_TICKS = 100;

	private final WriteThrottle throttle;
	private int lastWriteTick = Integer.MIN_VALUE;

	/**
	 * Starts dirty, so the first tick after starting writes a snapshot.
	 *
	 * @param intervalTicks minimum ticks between writes
	 */
	public SnapshotSchedule(int intervalTicks)
	{
		this.throttle = new WriteThrottle(intervalTicks);
		throttle.markDirty();
	}

	/**
	 * Records that something in the snapshot changed.
	 */
	public void markDirty()
	{
		throttle.markDirty();
	}

	/**
	 * @param tick current game tick count
	 * @return true when a snapshot should be written on this tick
	 */
	public boolean isDue(int tick)
	{
		if (lastWriteTick != Integer.MIN_VALUE && tick - lastWriteTick >= KEEPALIVE_TICKS)
		{
			throttle.markDirty();
		}
		if (!throttle.tryAcquire(tick))
		{
			return false;
		}
		lastWriteTick = tick;
		return true;
	}
}

package com.wiseoldclaude.snapshot;

import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;

/**
 * Decides which bank container slots represent items the player actually owns. The bank container also
 * holds placeholders (quantity 0, kept to reserve a slot) and bank fillers, which would otherwise be
 * reported to the assistant as owned items.
 */
public final class BankContents
{
	private BankContents()
	{
	}

	/**
	 * @param item one slot of the bank container
	 * @return true when the slot holds a real, owned stack
	 */
	public static boolean isStored(Item item)
	{
		return item.getId() >= 0 && item.getQuantity() > 0 && item.getId() != ItemID.BANK_FILLER;
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.model.BirdhouseSpace;
import com.wiseoldclaude.model.Birdhouses;
import com.wiseoldclaude.model.Position;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.function.Function;
import java.util.function.IntUnaryOperator;
import java.util.function.Supplier;
import net.runelite.api.gameval.VarPlayerID;

/**
 * Tracks each character's Fossil Island bird houses so "are my bird houses ready?" is answered away from the
 * island. Follows RuneLite's Time Tracking ({@code BirdHouseTracker}, client 1.13.1) in reading one varp per
 * space, and only on Fossil Island, but keeps its own record instead of reading that plugin's data. The game
 * reports what a space holds, not when seeds went in, so a ready time exists only for seeds the plugin saw go into
 * a built house during this session; a first reading after a restart keeps a remembered time only if nothing changed.
 * Not thread-safe: use only from the client thread.
 */
public class BirdhouseTracker
{
	/** Time from seeding to a full bird house; {@code BirdHouseTracker.BIRD_HOUSE_DURATION}. */
	static final Duration FILL_TIME = Duration.ofMinutes(50);

	/** {@code BirdHouseTracker.FOSSIL_ISLAND_REGIONS}: the varps only describe the spaces while here. */
	private static final Set<Integer> FOSSIL_ISLAND_REGIONS = Set.of(14650, 14651, 14652, 14906, 14907, 15162, 15163);

	/**
	 * More houses than this disappearing at once is the client still loading, not the player dismantling them;
	 * RuneLite ignores such readings the same way.
	 */
	private static final int MAX_VANISHED_AT_ONCE = 2;

	private static final String[] BIRDHOUSE_NAMES = {
		"Bird house", "Oak bird house", "Willow bird house", "Teak bird house", "Maple bird house",
		"Mahogany bird house", "Yew bird house", "Magic bird house", "Redwood bird house"};

	/**
	 * The spaces with RuneLite's names, in its order.
	 */
	private enum Space
	{
		MEADOW_NORTH("Mushroom Meadow (North)", VarPlayerID.BIRDHOUSE_TRANSMIT_A),
		MEADOW_SOUTH("Mushroom Meadow (South)", VarPlayerID.BIRDHOUSE_TRANSMIT_B),
		VALLEY_NORTH("Verdant Valley (Northeast)", VarPlayerID.BIRDHOUSE_TRANSMIT_C),
		VALLEY_SOUTH("Verdant Valley (Southwest)", VarPlayerID.BIRDHOUSE_TRANSMIT_D);

		private final String location;
		private final int varp;

		Space(String location, int varp)
		{
			this.location = location;
			this.varp = varp;
		}
	}

	private final Function<String, Birdhouses> previous;
	private final IntUnaryOperator varps;
	private final Supplier<Instant> clock;
	private final Map<String, Birdhouses> known = new HashMap<>();
	private final Set<String> watchedThisSession = new HashSet<>();

	/**
	 * @param previous loads a character's bird houses from its previous export, returning null when none
	 * @param varps reads a varp's current value
	 * @param clock the current time
	 */
	public BirdhouseTracker(Function<String, Birdhouses> previous, IntUnaryOperator varps, Supplier<Instant> clock)
	{
		this.previous = previous;
		this.varps = varps;
		this.clock = clock;
	}

	/**
	 * @param rsn the logged-in character
	 * @param position where the character stands
	 * @return the bird houses as last seen, or null when the character's have never been seen
	 */
	public Birdhouses observe(String rsn, Position position)
	{
		Birdhouses remembered = rememberedFor(rsn);
		if (!onFossilIsland(position))
		{
			return remembered;
		}
		Instant now = clock.get();
		Instant watchedAt = watchedThisSession.contains(rsn) ? now : null;
		List<BirdhouseSpace> spaces = new ArrayList<>();
		int vanished = 0;
		for (Space space : Space.values())
		{
			BirdhouseSpace prior = priorOf(remembered, space);
			BirdhouseSpace current = decode(space, varps.applyAsInt(space.varp));
			if (current.getState() == BirdhouseSpace.State.EMPTY && prior != null
				&& prior.getState() != BirdhouseSpace.State.EMPTY)
			{
				vanished++;
			}
			spaces.add(withReadyAt(current, prior, watchedAt));
		}
		if (vanished > MAX_VANISHED_AT_ONCE)
		{
			return remembered;
		}
		watchedThisSession.add(rsn);
		Birdhouses seen = new Birdhouses(now.toString(), spaces);
		known.put(rsn, seen);
		return seen;
	}

	/**
	 * Observing on every change of these, not only on snapshot writes, keeps a quick dismantle and reseed from
	 * looking like an untouched house.
	 *
	 * @param varpId the varp a {@code VarbitChanged} event reports
	 * @return whether it is one of the bird house spaces
	 */
	public static boolean watches(int varpId)
	{
		for (Space space : Space.values())
		{
			if (space.varp == varpId)
			{
				return true;
			}
		}
		return false;
	}

	private Birdhouses rememberedFor(String rsn)
	{
		if (!known.containsKey(rsn))
		{
			known.put(rsn, previous.apply(rsn));
		}
		return known.get(rsn);
	}

	private static boolean onFossilIsland(Position position)
	{
		return position != null && position.getPlane() == 0 && FOSSIL_ISLAND_REGIONS.contains(position.getRegionId());
	}

	private static BirdhouseSpace priorOf(Birdhouses remembered, Space space)
	{
		if (remembered == null || remembered.getSpaces() == null)
		{
			return null;
		}
		return remembered.getSpaces().stream()
			.filter(prior -> space.location.equals(prior.getLocation()))
			.findFirst()
			.orElse(null);
	}

	/**
	 * Decodes a space's varp as {@code BirdHouseState.fromVarpValue} and {@code BirdHouse.fromVarpValue} do:
	 * 0 is empty, then three values per bird house type in order, the third of which is seeded.
	 */
	private static BirdhouseSpace decode(Space space, int value)
	{
		if (value == 0)
		{
			return new BirdhouseSpace(space.location, BirdhouseSpace.State.EMPTY, null, null);
		}
		if (value < 0 || value > BIRDHOUSE_NAMES.length * 3)
		{
			return new BirdhouseSpace(space.location, BirdhouseSpace.State.UNKNOWN, null, null);
		}
		BirdhouseSpace.State state = value % 3 == 0 ? BirdhouseSpace.State.SEEDED : BirdhouseSpace.State.BUILT;
		return new BirdhouseSpace(space.location, state, BIRDHOUSE_NAMES[(value - 1) / 3], null);
	}

	/**
	 * Carries a seeded house's ready time: kept from the prior reading when nothing changed, or started from this
	 * reading when the seeding was watched happening.
	 *
	 * @param current the space as read now
	 * @param prior the space as last remembered, or null
	 * @param watchedAt when this reading was taken, or null when the plugin has not watched this character's spaces
	 *     yet this session, so a change cannot be timed
	 * @return the space with its ready time, or as read when it is not seeded
	 */
	private static BirdhouseSpace withReadyAt(BirdhouseSpace current, BirdhouseSpace prior, Instant watchedAt)
	{
		if (current.getState() != BirdhouseSpace.State.SEEDED)
		{
			return current;
		}
		String readyAt = null;
		if (unchanged(current, prior))
		{
			readyAt = prior.getReadyAt();
		}
		else if (watchedAt != null && seededJustNow(current, prior))
		{
			readyAt = watchedAt.plus(FILL_TIME).toString();
		}
		return new BirdhouseSpace(current.getLocation(), current.getState(), current.getBirdhouse(), readyAt);
	}

	/**
	 * Building a bird house and adding seeds are separate actions, so a seeding the plugin watched always arrives
	 * from the same house built empty. Any other arrival (from nothing, or from a reading taken while the client was
	 * still loading) is a seeding that happened unwatched.
	 */
	private static boolean seededJustNow(BirdhouseSpace current, BirdhouseSpace prior)
	{
		return prior != null && prior.getState() == BirdhouseSpace.State.BUILT
			&& Objects.equals(prior.getBirdhouse(), current.getBirdhouse());
	}

	private static boolean unchanged(BirdhouseSpace current, BirdhouseSpace prior)
	{
		return prior != null && prior.getState() == current.getState()
			&& Objects.equals(prior.getBirdhouse(), current.getBirdhouse());
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.combat.ActivePrayers;
import com.wiseoldclaude.combat.AttackStyles;
import com.wiseoldclaude.combat.HealthPercent;
import com.wiseoldclaude.combat.PrayerUpgrades;
import com.wiseoldclaude.combat.TimedEffectVars;
import com.wiseoldclaude.combat.TimedEffects;
import com.wiseoldclaude.common.Positions;
import com.wiseoldclaude.model.AccountType;
import com.wiseoldclaude.model.Bank;
import com.wiseoldclaude.model.CombatAchievements;
import com.wiseoldclaude.model.CombatState;
import com.wiseoldclaude.model.CombatTarget;
import com.wiseoldclaude.model.ExchangeOffer;
import com.wiseoldclaude.model.ItemStack;
import com.wiseoldclaude.model.PlayerSnapshot;
import com.wiseoldclaude.model.PlayerStatus;
import com.wiseoldclaude.model.PoisonStatus;
import com.wiseoldclaude.model.Progress;
import com.wiseoldclaude.model.SkillLevel;
import com.wiseoldclaude.model.SlayerProgress;
import com.wiseoldclaude.model.SlayerTask;
import com.wiseoldclaude.model.Spellbook;
import com.wiseoldclaude.progress.AchievementDiaries;
import com.wiseoldclaude.progress.CombatAchievementTiers;
import com.wiseoldclaude.progress.SlayerStreaks;
import com.wiseoldclaude.progress.SlayerTasks;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.ParamID;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

/**
 * Adapter that reads live client state into a {@link PlayerSnapshot}. Kept free of logic beyond mapping so
 * everything decision-bearing lives in classes testable without a running client.
 * Must be called on the client thread: item compositions and varbits are only safe to read there.
 */
public class SnapshotCollector
{
	/** {@code Client#getEnergy} counts hundredths of a percent. */
	private static final int RUN_ENERGY_UNITS_PER_PERCENT = 100;

	/** {@code VarPlayerID.SA_ENERGY} counts tenths of a percent, as RuneLite's status bars divide it. */
	private static final int SPECIAL_ATTACK_UNITS_PER_PERCENT = 10;

	private final Client client;
	private final ItemManager itemManager;

	@Inject
	public SnapshotCollector(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/**
	 * Captures the current state of the logged-in character.
	 *
	 * @return the snapshot, or null while no player is loaded (login screen, hopping)
	 */
	public PlayerSnapshot collect()
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null)
		{
			return null;
		}

		AccountType accountType = AccountType.fromVarbit(client.getVarbitValue(VarbitID.IRONMAN));
		return PlayerSnapshot.builder()
			.rsn(player.getName())
			.accountType(accountType)
			.capturedAt(Instant.now().toString())
			.world(client.getWorld())
			.combatLevel(player.getCombatLevel())
			.position(Positions.of(player.getWorldLocation()))
			.skills(skills())
			.inventory(inventory())
			.equipment(equipment())
			.combat(combat(player))
			.status(status())
			.gameRevision(client.getRevision())
			.progress(progress())
			.worldTypes(WorldTypes.names(client.getWorldType()))
			.nearbyPlayers(nearbyPlayers(player))
			.grandExchange(accountType.canUseGrandExchange() ? grandExchange() : null)
			.build();
	}

	/**
	 * Reads slayer, diary and combat achievement progress. Session XP is left null: it needs the baseline the
	 * plugin keeps across snapshots, so the plugin fills it in.
	 *
	 * @return progress without session XP
	 */
	private Progress progress()
	{
		return Progress.builder()
			.slayer(slayer())
			.diaries(AchievementDiaries.decode(client::getVarbitValue))
			.combatAchievements(new CombatAchievements(
				client.getVarbitValue(VarbitID.CA_POINTS),
				CombatAchievementTiers.completed(client::getVarbitValue)))
			.build();
	}

	private SlayerProgress slayer()
	{
		SlayerStreaks streaks = new SlayerStreaks(
			client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED),
			client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED),
			client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED));
		return new SlayerProgress(
			slayerTask(),
			client.getVarbitValue(VarbitID.SLAYER_POINTS),
			streaks.forMaster(client.getVarbitValue(VarbitID.SLAYER_MASTER)));
	}

	/**
	 * Resolves the task's name and area through the game cache's slayer tables, as RuneLite's slayer plugin does.
	 * A failed lookup leaves that part null instead of dropping the task, so the kill count still reaches Claude.
	 */
	private SlayerTask slayerTask()
	{
		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (!SlayerTasks.isAssigned(remaining))
		{
			return null;
		}
		Integer taskRow = slayerTaskRow(client.getVarpValue(VarPlayerID.SLAYER_TARGET));
		String name = taskRow == null ? null : (String) firstField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE);
		String area = slayerArea(client.getVarpValue(VarPlayerID.SLAYER_AREA));
		return new SlayerTask(SlayerTasks.displayName(name), remaining, area);
	}

	private Integer slayerTaskRow(int targetId)
	{
		if (SlayerTasks.isBossTask(targetId))
		{
			List<Integer> bossRows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			return bossRows.isEmpty() ? null : (Integer) firstField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK);
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, targetId);
		return rows.isEmpty() ? null : rows.get(0);
	}

	private String slayerArea(int areaId)
	{
		if (!SlayerTasks.hasArea(areaId))
		{
			return null;
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
		return rows.isEmpty() ? null : (String) firstField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER);
	}

	private Object firstField(int row, int column)
	{
		Object[] values = client.getDBTableField(row, column, 0);
		return values.length == 0 ? null : values[0];
	}

	/**
	 * Counts the other players in the loaded scene. Only the number is exported, never who they are or where.
	 *
	 * @param local the local player, excluded from the count
	 * @return other players nearby, or null while no scene is loaded
	 */
	private Integer nearbyPlayers(Player local)
	{
		WorldView view = client.getTopLevelWorldView();
		if (view == null)
		{
			return null;
		}
		return (int) view.players().stream().filter(other -> other != null && other != local).count();
	}

	/**
	 * Reads the combat setup and the player's current target.
	 *
	 * @param player the local player
	 * @return the combat state
	 */
	private CombatState combat(Player player)
	{
		return CombatState.builder()
			.target(targetOf(player.getInteracting()))
			.attackStyle(AttackStyles.decode(
				weaponStyleNames(client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY)),
				client.getVarpValue(VarPlayerID.COM_MODE),
				client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE)))
			.spellbook(Spellbook.fromVarbit(client.getVarbitValue(VarbitID.SPELLBOOK)))
			.activePrayers(ActivePrayers.names(prayersOn(), PrayerUpgrades.fromVarbits(
				client.getVarbitValue(VarbitID.PRAYER_DEADEYE_UNLOCKED),
				client.getVarbitValue(VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED),
				client.getVarbitValue(VarbitID.BR_INGAME))))
			.specialAttackPercent(client.getVarpValue(VarPlayerID.SA_ENERGY) / SPECIAL_ATTACK_UNITS_PER_PERCENT)
			.build();
	}

	/**
	 * Reads run energy, weight, poison, disease and timed effects.
	 *
	 * @return the status
	 */
	private PlayerStatus status()
	{
		int poison = client.getVarpValue(VarPlayerID.POISON);
		return PlayerStatus.builder()
			.runEnergyPercent(client.getEnergy() / RUN_ENERGY_UNITS_PER_PERCENT)
			.weightKg(client.getWeight())
			.poison(PoisonStatus.fromVarp(poison))
			.poisonDamage(PoisonStatus.nextHit(poison))
			.diseased(client.getVarpValue(VarPlayerID.DISEASE) > 0)
			.effects(TimedEffects.decode(timedEffectVars(poison)))
			.build();
	}

	/**
	 * Only another player's combat level leaves the client; NPCs are named so Claude can look them up.
	 */
	private static CombatTarget targetOf(Actor actor)
	{
		if (actor instanceof NPC)
		{
			NPC npc = (NPC) actor;
			return CombatTarget.npc(npc.getName(), npc.getCombatLevel(), npc.getId())
				.withHpPercent(HealthPercent.of(npc.getHealthRatio(), npc.getHealthScale()));
		}
		if (actor instanceof Player)
		{
			return CombatTarget.player(actor.getCombatLevel());
		}
		return null;
	}

	/**
	 * The equipped weapon's style names per slot, read from the game cache as RuneLite's attack styles plugin
	 * does (weapon-styles enum, then each style struct's name param).
	 */
	private List<String> weaponStyleNames(int weaponCategory)
	{
		int stylesEnum = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(weaponCategory);
		if (stylesEnum == -1)
		{
			return AttackStyles.fallbackStyles(weaponCategory);
		}
		List<String> names = new ArrayList<>();
		for (int structId : client.getEnum(stylesEnum).getIntVals())
		{
			names.add(client.getStructComposition(structId).getStringValue(ParamID.ATTACK_STYLE_NAME));
		}
		return names;
	}

	private Set<Prayer> prayersOn()
	{
		Set<Prayer> on = EnumSet.noneOf(Prayer.class);
		for (Prayer prayer : Prayer.values())
		{
			if (client.getVarbitValue(prayer.getVarbit()) != 0)
			{
				on.add(prayer);
			}
		}
		return on;
	}

	private TimedEffectVars timedEffectVars(int poison)
	{
		return TimedEffectVars.builder()
			.staminaActive(client.getVarbitValue(VarbitID.STAMINA_ACTIVE))
			.staminaDuration(client.getVarbitValue(VarbitID.STAMINA_DURATION))
			.antifire(client.getVarbitValue(VarbitID.ANTIFIRE_POTION))
			.superAntifire(client.getVarbitValue(VarbitID.SUPER_ANTIFIRE_POTION))
			.poison(poison)
			.nmzOverload(client.getVarbitValue(VarbitID.NZONE_OVERLOAD_POTION_EFFECTS))
			.raidsOverload(client.getVarbitValue(VarbitID.RAIDS_OVERLOAD_TIMER))
			.divineSuperAttack(client.getVarbitValue(VarbitID.DIVINEATTACK_POTION_TIME))
			.divineSuperStrength(client.getVarbitValue(VarbitID.DIVINESTRENGTH_POTION_TIME))
			.divineSuperDefence(client.getVarbitValue(VarbitID.DIVINEDEFENCE_POTION_TIME))
			.divineRanging(client.getVarbitValue(VarbitID.DIVINERANGE_POTION_TIME))
			.divineMagic(client.getVarbitValue(VarbitID.DIVINEMAGIC_POTION_TIME))
			.divineSuperCombat(client.getVarbitValue(VarbitID.DIVINECOMBAT_POTION_TIME))
			.divineBastion(client.getVarbitValue(VarbitID.DIVINEBASTION_POTION_TIME))
			.divineBattlemage(client.getVarbitValue(VarbitID.DIVINEBATTLEMAGE_POTION_TIME))
			.moonlightPotion(client.getVarbitValue(VarbitID.MOONLIGHT_POTION_TIME))
			.teleblock(client.getVarbitValue(VarbitID.TELEBLOCK_CYCLES))
			.build();
	}

	/**
	 * Captures the bank from its container. Only meaningful while the bank is open, which is why callers
	 * capture on the container's change event and remember the result.
	 *
	 * @param container the bank container ({@code InventoryID.BANK})
	 * @return the owned bank items, timestamped now
	 */
	public Bank bankOf(ItemContainer container)
	{
		List<ItemStack> items = new ArrayList<>();
		for (Item item : container.getItems())
		{
			if (BankContents.isStored(item))
			{
				items.add(stackOf(item));
			}
		}
		return new Bank(Instant.now().toString(), items);
	}

	private Map<String, SkillLevel> skills()
	{
		Map<String, SkillLevel> skills = new LinkedHashMap<>();
		for (Skill skill : Skill.values())
		{
			skills.put(skill.name(), new SkillLevel(
				client.getRealSkillLevel(skill),
				client.getSkillExperience(skill),
				client.getBoostedSkillLevel(skill)));
		}
		return skills;
	}

	private List<ItemStack> inventory()
	{
		ItemContainer container = client.getItemContainer(InventoryID.INV);
		if (container == null)
		{
			return Collections.emptyList();
		}
		List<ItemStack> items = new ArrayList<>();
		for (Item item : container.getItems())
		{
			if (isPresent(item))
			{
				items.add(stackOf(item));
			}
		}
		return items;
	}

	private Map<String, ItemStack> equipment()
	{
		Map<String, ItemStack> equipped = new LinkedHashMap<>();
		ItemContainer container = client.getItemContainer(InventoryID.WORN);
		if (container == null)
		{
			return equipped;
		}
		for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
		{
			Item item = container.getItem(slot.getSlotIdx());
			if (isPresent(item))
			{
				equipped.put(slot.name(), stackOf(item));
			}
		}
		return equipped;
	}

	private List<ExchangeOffer> grandExchange()
	{
		return ExchangeOffers.of(client.getGrandExchangeOffers(), id -> itemManager.getItemComposition(id).getName());
	}

	private static boolean isPresent(Item item)
	{
		return item != null && item.getId() >= 0 && item.getQuantity() > 0;
	}

	private ItemStack stackOf(Item item)
	{
		String name = itemManager.getItemComposition(item.getId()).getName();
		return new ItemStack(item.getId(), name, item.getQuantity());
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.model.Bank;
import com.wiseoldclaude.model.ItemStack;
import java.util.List;
import net.runelite.api.gameval.ItemID;

/**
 * Sums the player's coins so the assistant can answer "can I afford X" without adding up containers itself.
 * Uses {@code gameval.ItemID.COINS} (995): the deprecated {@code net.runelite.api.ItemID.COINS} is a
 * different item (617).
 */
public final class CoinCount
{
	private CoinCount()
	{
	}

	/**
	 * Totals coins carried plus coins in the last-seen bank. Returned as a long because a full inventory
	 * stack and a full bank stack together exceed {@link Integer#MAX_VALUE}.
	 *
	 * @param inventory current inventory stacks
	 * @param bank last-seen bank, or null when never seen
	 * @return total coins
	 */
	public static long total(List<ItemStack> inventory, Bank bank)
	{
		long total = coinsIn(inventory);
		if (bank != null)
		{
			total += coinsIn(bank.getItems());
		}
		return total;
	}

	private static long coinsIn(List<ItemStack> stacks)
	{
		long coins = 0;
		for (ItemStack stack : stacks)
		{
			if (stack.getId() == ItemID.COINS)
			{
				coins += stack.getQty();
			}
		}
		return coins;
	}
}

package com.wiseoldclaude.snapshot;

import com.google.gson.Gson;
import com.wiseoldclaude.io.CharacterFileWriter;
import com.wiseoldclaude.io.OutputDirectory;
import com.wiseoldclaude.model.PlayerSnapshot;
import java.io.IOException;
import javax.inject.Inject;
import net.runelite.client.util.Filepath;

/**
 * Persists snapshots as one JSON file per character.
 */
public class SnapshotWriter
{
	private final CharacterFileWriter files;

	/**
	 * Writes nulls: the file format requires optional-by-nature fields such as {@code bank} to be present as an explicit
	 * null.
	 *
	 * @param gson the client's shared Gson
	 * @param directory where the plugin's files go
	 */
	@Inject
	public SnapshotWriter(Gson gson, OutputDirectory directory)
	{
		this.files = CharacterFileWriter.writingNulls(gson, directory);
	}

	/**
	 * Writes the file, replacing any previous one for the same character.
	 *
	 * @param snapshot the value to persist
	 * @return the written file
	 * @throws IOException if the directory cannot be created or the file cannot be written
	 */
	public Filepath write(PlayerSnapshot snapshot) throws IOException
	{
		return files.write(snapshot.getRsn(), snapshot);
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.model.SessionXp;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Tracks XP gained since the player logged in. The baseline waits two ticks after a login or world hop, as
 * RuneLite's XP tracker does, because the client reports zero XP until the login stat sync lands. A hop keeps the
 * session; a fresh login starts a new one. XP never falls within one account profile, so a skill reading below its
 * baseline means a different profile (e.g. a seasonal world) and also starts a new session.
 * Not thread-safe: used on the client thread only.
 */
public class SessionXpTracker
{
	private static final int SYNC_TICKS = 2;

	private int ticksUntilSynced;
	private Map<String, Integer> baseline;
	private String since;

	/** Starts a new session once the login stat sync has landed. */
	public void onLogin()
	{
		baseline = null;
		ticksUntilSynced = SYNC_TICKS;
	}

	/** Pauses reporting while a world hop resyncs stats, keeping the session. */
	public void onHop()
	{
		ticksUntilSynced = SYNC_TICKS;
	}

	/** Counts down the stat sync after a login or hop. */
	public void onTick()
	{
		if (ticksUntilSynced > 0)
		{
			ticksUntilSynced--;
		}
	}

	/**
	 * Reports the session's gains, starting the session if there is none yet.
	 *
	 * @param xp current XP per skill name
	 * @param now when the XP was read, which becomes the session start for a new session
	 * @return gains per skill that gained XP, or null while stats are still syncing
	 */
	public SessionXp observe(Map<String, Integer> xp, Instant now)
	{
		if (ticksUntilSynced > 0)
		{
			return null;
		}
		if (baseline == null || anyBelowBaseline(xp))
		{
			baseline = new LinkedHashMap<>(xp);
			since = now.toString();
		}
		return new SessionXp(since, gains(xp));
	}

	private boolean anyBelowBaseline(Map<String, Integer> xp)
	{
		return xp.entrySet().stream().anyMatch(skill -> skill.getValue() < baseline.getOrDefault(skill.getKey(), 0));
	}

	private Map<String, Integer> gains(Map<String, Integer> xp)
	{
		Map<String, Integer> gained = new LinkedHashMap<>();
		for (Map.Entry<String, Integer> skill : xp.entrySet())
		{
			int delta = skill.getValue() - baseline.getOrDefault(skill.getKey(), skill.getValue());
			if (delta > 0)
			{
				gained.put(skill.getKey(), delta);
			}
		}
		return gained;
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.model.Bank;
import com.wiseoldclaude.model.PlayerSnapshot;
import com.wiseoldclaude.model.Position;
import com.wiseoldclaude.model.SkillLevel;
import com.wiseoldclaude.quests.QuestSummary;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import java.util.function.Supplier;

/**
 * Completes a live snapshot with what the client cannot show at that moment: the bank as last opened, bird houses
 * as last seen on Fossil Island, XP gained this session and the quests as last read. Holds that memory for one plugin
 * run. Not thread-safe: use only from the client thread.
 */
public class SnapshotAssembler
{
	private final BankMemory bankMemory;
	private final BirdhouseTracker birdhouses;
	private final SessionXpTracker sessionXp = new SessionXpTracker();
	private final Supplier<Instant> clock;

	/**
	 * @param previous the last export, which seeds the bank and bird houses until the player shows them again
	 * @param varps reads a varp's current value
	 */
	public SnapshotAssembler(PreviousSnapshotReader previous, IntUnaryOperator varps)
	{
		this(previous, varps, Instant::now);
	}

	/**
	 * @param previous the last export, which seeds the bank and bird houses until the player shows them again
	 * @param varps reads a varp's current value
	 * @param clock the current time
	 */
	SnapshotAssembler(PreviousSnapshotReader previous, IntUnaryOperator varps, Supplier<Instant> clock)
	{
		this.bankMemory = new BankMemory(previous::lastBank);
		this.birdhouses = new BirdhouseTracker(previous::lastBirdhouses, varps, clock);
		this.clock = clock;
	}

	/**
	 * @param rsn the character whose bank was opened
	 * @param bank the bank's contents
	 */
	public void rememberBank(String rsn, Bank bank)
	{
		bankMemory.record(rsn, bank);
	}

	/**
	 * Reads the bird house spaces on every change, not only on snapshot writes, so a quick dismantle and reseed is
	 * not mistaken for an untouched house.
	 *
	 * @param rsn the logged-in character
	 * @param position where the character stands
	 */
	public void observeBirdhouses(String rsn, Position position)
	{
		birdhouses.observe(rsn, position);
	}

	/** Starts a new XP session once the login stat sync has landed. */
	public void onLogin()
	{
		sessionXp.onLogin();
	}

	/** Keeps the XP session across a world hop while stats resync. */
	public void onHop()
	{
		sessionXp.onHop();
	}

	/** Counts down the stat sync after a login or hop. */
	public void onTick()
	{
		sessionXp.onTick();
	}

	/**
	 * @param live the snapshot as read from the client this tick
	 * @param quests the quests as last read
	 * @return the snapshot to write
	 */
	public PlayerSnapshot complete(PlayerSnapshot live, QuestSummary quests)
	{
		Bank bank = bankMemory.bankFor(live.getRsn());
		return live.toBuilder()
			.bank(bank)
			.coins(CoinCount.total(live.getInventory(), bank))
			.quests(quests.getQuests())
			.questPoints(quests.getQuestPoints())
			.fairyRingsUnlocked(quests.getFairyRingsUnlocked())
			.birdhouses(birdhouses.observe(live.getRsn(), live.getPosition()))
			.progress(live.getProgress().toBuilder()
				.sessionXp(sessionXp.observe(xpBySkill(live.getSkills()), clock.get()))
				.build())
			.build();
	}

	private static Map<String, Integer> xpBySkill(Map<String, SkillLevel> skills)
	{
		Map<String, Integer> xp = new LinkedHashMap<>();
		skills.forEach((name, skill) -> xp.put(name, (int) skill.getXp()));
		return xp;
	}
}

package com.wiseoldclaude.snapshot;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import com.wiseoldclaude.io.AtomicFiles;
import com.wiseoldclaude.io.CharacterFiles;
import com.wiseoldclaude.io.OutputDirectory;
import com.wiseoldclaude.model.Bank;
import com.wiseoldclaude.model.Birdhouses;
import java.io.IOException;
import javax.inject.Inject;

/**
 * Recovers state from a character's previously exported snapshot, so data the game only exposes
 * intermittently (the bank, bird houses) survives a client restart. Any unreadable, outdated, or incomplete
 * file yields "nothing known" rather than an error: losing stale state is preferable to failing the export.
 */
public class PreviousSnapshotReader
{
	private final Gson gson;
	private final OutputDirectory directory;

	/**
	 * @param gson deserializer matching the one the snapshots were written with
	 * @param directory where {@link SnapshotWriter} puts snapshots
	 */
	@Inject
	public PreviousSnapshotReader(Gson gson, OutputDirectory directory)
	{
		this.gson = gson;
		this.directory = directory;
	}

	/**
	 * @param rsn character whose previous export to read
	 * @return the bank recorded in that export, or null when there is none or it cannot be trusted
	 */
	public Bank lastBank(String rsn)
	{
		Bank bank = lastField(rsn, "bank", Bank.class);
		return bank == null || bank.getCapturedAt() == null || bank.getItems() == null ? null : bank;
	}

	/**
	 * @param rsn character whose previous export to read
	 * @return the bird houses recorded in that export, or null when there are none or they cannot be trusted
	 */
	public Birdhouses lastBirdhouses(String rsn)
	{
		Birdhouses birdhouses = lastField(rsn, "birdhouses", Birdhouses.class);
		return birdhouses == null || birdhouses.getCheckedAt() == null || birdhouses.getSpaces() == null ? null : birdhouses;
	}

	private <T> T lastField(String rsn, String field, Class<T> type)
	{
		try
		{
			String json = AtomicFiles.read(CharacterFiles.pathFor(rsn, directory.get()));
			JsonElement value = new JsonParser().parse(json).getAsJsonObject().get(field);
			return value == null || value.isJsonNull() ? null : gson.fromJson(value, type);
		}
		catch (IOException | JsonParseException | IllegalStateException e)
		{
			return null;
		}
	}
}

package com.wiseoldclaude.snapshot;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.WorldType;

/**
 * Names the rulesets of the world the player is on ({@code Client#getWorldType}) in game terms. Mapped from an
 * explicit list rather than {@link WorldType#name()} so a flag RuneLite adds later can never leak a value the
 * file format does not know, and so {@code pvp} and {@code bounty_hunter} match the MCP server's {@code find_nearest}
 * world types exactly. {@code LEGACY_ONLY} and {@code EOC_ONLY} are client combat-display modes, not rulesets the
 * player's advice depends on, so they are left out.
 */
public final class WorldTypes
{
	private static final Map<WorldType, String> NAMES = new EnumMap<>(WorldType.class);

	static
	{
		NAMES.put(WorldType.MEMBERS, "members");
		NAMES.put(WorldType.PVP, "pvp");
		NAMES.put(WorldType.BOUNTY, "bounty_hunter");
		NAMES.put(WorldType.PVP_ARENA, "pvp_arena");
		NAMES.put(WorldType.SKILL_TOTAL, "skill_total");
		NAMES.put(WorldType.QUEST_SPEEDRUNNING, "quest_speedrunning");
		NAMES.put(WorldType.HIGH_RISK, "high_risk");
		NAMES.put(WorldType.LAST_MAN_STANDING, "last_man_standing");
		NAMES.put(WorldType.BETA_WORLD, "beta");
		NAMES.put(WorldType.NOSAVE_MODE, "no_save");
		NAMES.put(WorldType.TOURNAMENT_WORLD, "tournament");
		NAMES.put(WorldType.FRESH_START_WORLD, "fresh_start");
		NAMES.put(WorldType.DEADMAN, "deadman");
		NAMES.put(WorldType.SEASONAL, "seasonal");
	}

	private WorldTypes()
	{
	}

	/**
	 * Names the world's rulesets.
	 *
	 * @param types the world's type flags
	 * @return file-format names in {@link WorldType} declaration order; empty for a standard free-to-play world
	 */
	public static List<String> names(Set<WorldType> types)
	{
		List<String> names = new ArrayList<>();
		for (Map.Entry<WorldType, String> entry : NAMES.entrySet())
		{
			if (types.contains(entry.getKey()))
			{
				names.add(entry.getValue());
			}
		}
		return names;
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.model.ExchangeOffer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.IntFunction;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Decodes the client's Grand Exchange slots. The client receives every slot at login and on each change, so
 * reading them on every snapshot write needs no memory of its own.
 */
final class ExchangeOffers
{
	private ExchangeOffers()
	{
	}

	/**
	 * @param slots the client's offers, indexed by slot; null entries and empty slots are skipped
	 * @param itemName resolves an item id to its name
	 * @return the occupied slots in slot order; empty when there are none
	 */
	static List<ExchangeOffer> of(GrandExchangeOffer[] slots, IntFunction<String> itemName)
	{
		if (slots == null)
		{
			return Collections.emptyList();
		}
		List<ExchangeOffer> offers = new ArrayList<>();
		for (int i = 0; i < slots.length; i++)
		{
			GrandExchangeOffer offer = slots[i];
			if (offer == null || offer.getState() == null || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}
			offers.add(ExchangeOffer.builder()
				.slot(i + 1)
				.itemId(offer.getItemId())
				.itemName(itemName.apply(offer.getItemId()))
				.side(sideOf(offer.getState()))
				.status(statusOf(offer.getState()))
				.pricePerItem(offer.getPrice())
				.quantity(offer.getTotalQuantity())
				.quantityTraded(offer.getQuantitySold())
				.coinsTraded(offer.getSpent())
				.build());
		}
		return offers;
	}

	private static ExchangeOffer.Side sideOf(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return ExchangeOffer.Side.BUY;
			default:
				return ExchangeOffer.Side.SELL;
		}
	}

	private static ExchangeOffer.Status statusOf(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BOUGHT:
			case SOLD:
				return ExchangeOffer.Status.COMPLETE;
			case CANCELLED_BUY:
			case CANCELLED_SELL:
				return ExchangeOffer.Status.CANCELLED;
			default:
				return ExchangeOffer.Status.ACTIVE;
		}
	}
}

package com.wiseoldclaude.snapshot;

import com.wiseoldclaude.model.Bank;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

/**
 * Remembers each character's last-seen bank. The game exposes the bank only while it is open, so without
 * memory every snapshot written after closing it, or after a client restart, would lose the bank. A
 * character's first lookup is seeded from the previously exported snapshot; a bank captured live always
 * wins over the seed, even when captured before the first lookup.
 * Not thread-safe: use only from the client thread.
 */
public class BankMemory
{
	private final Function<String, Bank> previousBank;
	private final Map<String, Bank> banks = new HashMap<>();

	/**
	 * @param previousBank loads a character's bank from its previous export, returning null when none
	 */
	public BankMemory(Function<String, Bank> previousBank)
	{
		this.previousBank = previousBank;
	}

	/**
	 * Records the bank as just seen in the client.
	 *
	 * @param rsn character the bank belongs to
	 * @param bank current bank contents
	 */
	public void record(String rsn, Bank bank)
	{
		banks.put(rsn, bank);
	}

	/**
	 * @param rsn character to look up
	 * @return the most recent bank known for the character, or null when it has never been seen
	 */
	public Bank bankFor(String rsn)
	{
		if (!banks.containsKey(rsn))
		{
			banks.put(rsn, previousBank.apply(rsn));
		}
		return banks.get(rsn);
	}
}

package com.wiseoldclaude.common;

/**
 * Coalesces bursts of state changes into at most one snapshot write per interval. Inventory and stat
 * events fire many times per tick while skilling; writing on each would thrash the disk for no gain.
 * Tick-driven rather than clock-driven so it stays deterministic and testable.
 */
public class WriteThrottle
{
	private final int intervalTicks;
	private boolean dirty;
	private int lastWriteTick = Integer.MIN_VALUE;

	public WriteThrottle(int intervalTicks)
	{
		this.intervalTicks = intervalTicks;
	}

	/**
	 * Records that the snapshot is out of date.
	 */
	public void markDirty()
	{
		dirty = true;
	}

	/**
	 * Claims the right to write on this tick, clearing the pending change if granted.
	 *
	 * @param tick current game tick count
	 * @return true when a change is pending and the interval since the last write has elapsed
	 */
	public boolean tryAcquire(int tick)
	{
		boolean intervalElapsed = lastWriteTick == Integer.MIN_VALUE || tick - lastWriteTick >= intervalTicks;
		if (!dirty || !intervalElapsed)
		{
			return false;
		}
		dirty = false;
		lastWriteTick = tick;
		return true;
	}
}

