package com.wiseoldclaude.guidance;

import java.io.IOException;
import java.util.Objects;
import net.runelite.client.util.Filepath;

/**
 * Tells the plugin when the guidance request file changed, so it is parsed only then rather than on every
 * poll. Polled from the game tick: one metadata read per tick is negligible next to a WatchService, which
 * would need its own thread, lifecycle, and hand-off back to the client thread. Size is compared alongside
 * the modification time because some filesystems record times in whole seconds, and two requests written
 * within one second would otherwise look identical.
 */
public class GuidanceInbox
{
	private final Filepath file;
	private String lastSignature;

	/**
	 * @param file the request file, which need not exist yet
	 */
	public GuidanceInbox(Filepath file)
	{
		this.file = file;
	}

	/**
	 * @return true when the file appeared, disappeared, or was rewritten since the previous call
	 */
	public boolean hasChanged()
	{
		String signature = signature();
		if (Objects.equals(signature, lastSignature))
		{
			return false;
		}
		lastSignature = signature;
		return true;
	}

	/**
	 * @return the watched file
	 */
	public Filepath file()
	{
		return file;
	}

	private String signature()
	{
		try
		{
			return file.getLastModifiedTime().toMillis() + ":" + file.size();
		}
		catch (IOException e)
		{
			return null;
		}
	}
}

package com.wiseoldclaude.guidance;

/**
 * Where guidance becomes visible in the client. Kept apart from {@link GuidanceState} so the decisions of
 * when to guide can be tested without a running client, and so the drawing side may only ever draw:
 * implementations must never send input or move the player.
 */
public interface GuidanceDisplay
{
	/**
	 * Starts guiding to the request's target, replacing whatever was shown before.
	 *
	 * @param request the destination to guide to
	 */
	void show(GuidanceRequest request);

	/**
	 * The player reached the target: remove what only helps on the way there.
	 *
	 * @param request the destination that was reached
	 */
	void arrived(GuidanceRequest request);

	/**
	 * Guidance was cancelled before arrival: remove everything shown for it.
	 *
	 * @param request the destination no longer wanted
	 */
	void withdraw(GuidanceRequest request);
}

package com.wiseoldclaude.guidance;

import java.time.Duration;
import java.time.Instant;
import net.runelite.api.coords.WorldPoint;

/**
 * Decides when guidance starts, ends on arrival, or is withdrawn. Each distinct request is acted on at most
 * once: re-reading the same file after the player arrived must not draw the route again, while asking for
 * the same tile anew (a later request time) must. A request already older than the maximum age when first
 * seen is ignored, which keeps a file left over from an earlier session from guiding the player when the
 * client starts. Not thread-safe: use only from the client thread.
 */
public class GuidanceState
{
	private final GuidanceDisplay display;
	private final Duration maxAge;
	private final int arrivalRadius;

	private GuidanceRequest lastSeen;
	private GuidanceRequest active;

	/**
	 * @param display where guidance is drawn
	 * @param maxAge how old a request may be when first seen and still be followed
	 * @param arrivalRadius tiles from the target (same floor, diagonals count as one) that count as arrived
	 */
	public GuidanceState(GuidanceDisplay display, Duration maxAge, int arrivalRadius)
	{
		this.display = display;
		this.maxAge = maxAge;
		this.arrivalRadius = arrivalRadius;
	}

	/**
	 * Applies the request file's current content.
	 *
	 * @param latest the request in the file, or null when the file is gone or unreadable
	 * @param now the current time, for the staleness check
	 */
	public void onRequest(GuidanceRequest latest, Instant now)
	{
		if (latest != null && latest.equals(lastSeen))
		{
			return;
		}
		lastSeen = latest;
		if (latest == null || latest.getRequestedAt().isBefore(now.minus(maxAge)))
		{
			stop();
			return;
		}
		active = latest;
		display.show(latest);
	}

	/**
	 * @param position the player's current tile
	 */
	public void onPlayerAt(WorldPoint position)
	{
		if (active != null && position.distanceTo(active.getTarget()) <= arrivalRadius)
		{
			GuidanceRequest reached = active;
			active = null;
			display.arrived(reached);
		}
	}

	/**
	 * Withdraws any active guidance, e.g. when the plugin shuts down, so nothing it drew outlives it.
	 */
	public void stop()
	{
		if (active != null)
		{
			GuidanceRequest withdrawn = active;
			active = null;
			display.withdraw(withdrawn);
		}
	}
}

