import java.time.Instant;
import lombok.Value;
import net.runelite.api.coords.WorldPoint;

/**
 * A destination the MCP server asked the plugin to guide the player to. Equality covers the request time,
 * so asking for the same tile again counts as a new request even after the player arrived at it once.
 */
@Value
public class GuidanceRequest
{
	WorldPoint target;
	/**
	 * Human-readable destination name, or null when the server gave none.
	 */
	String label;
	Instant requestedAt;
}

package com.wiseoldclaude.guidance;

import java.time.Duration;
import java.time.Instant;
import java.util.function.Supplier;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Filepath;

/**
 * Follows the guidance request the MCP server writes: reads the request file when it changes, draws the route, and
 * reports arrival once the player gets there. Call {@link #onTick} and {@link #stop} on the client thread, where the
 * display may draw.
 */
public class GuidanceRefresh
{
	/**
	 * Written by the MCP server's guide_to tool. A subdirectory, so the server's listing of {@code *.json} character
	 * snapshots never mistakes the request for a character.
	 */
	static final String DIRECTORY = "guidance";
	static final String FILE = "request.json";

	/**
	 * The server writes requests seconds before the plugin sees them, so anything older is a leftover from an earlier
	 * session that must not guide the player as soon as the client starts.
	 */
	static final Duration MAX_AGE = Duration.ofMinutes(5);

	/**
	 * Close enough to see the target on screen. Inside Shortest Path's default finish distance of 5, so the hint
	 * arrow still leads the last steps after the route has ended.
	 */
	private static final int ARRIVAL_RADIUS_TILES = 2;

	private final GuidanceInbox inbox;
	private final GuidanceRequestReader reader = new GuidanceRequestReader();
	private final GuidanceState state;
	private final Supplier<Instant> clock;

	/**
	 * @param inbox watches the request file
	 * @param display draws and withdraws the route
	 * @param clock the current time, for the staleness check
	 */
	GuidanceRefresh(GuidanceInbox inbox, GuidanceDisplay display, Supplier<Instant> clock)
	{
		this.inbox = inbox;
		this.state = new GuidanceState(display, MAX_AGE, ARRIVAL_RADIUS_TILES);
		this.clock = clock;
	}

	/**
	 * @param directory the plugin's data directory, which holds the request file
	 * @param display draws and withdraws the route in the client
	 * @return a refresh following the request file in that directory
	 */
	public static GuidanceRefresh in(Filepath directory, GuidanceDisplay display)
	{
		GuidanceInbox inbox = new GuidanceInbox(directory.joinSegment(DIRECTORY).joinSegment(FILE));
		return new GuidanceRefresh(inbox, display, Instant::now);
	}

	/**
	 * Applies a changed request, then checks whether the player has arrived.
	 *
	 * @param playerPosition the player's tile, or null while no player is logged in
	 */
	public void onTick(WorldPoint playerPosition)
	{
		if (inbox.hasChanged())
		{
			state.onRequest(reader.read(inbox.file()), clock.get());
		}
		if (playerPosition != null)
		{
			state.onPlayerAt(playerPosition);
		}
	}

	/**
	 * Withdraws any active guidance, so nothing the plugin drew outlives it.
	 */
	public void stop()
	{
		state.stop();
	}
}

package com.wiseoldclaude.guidance;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import com.google.gson.JsonPrimitive;
import com.wiseoldclaude.io.AtomicFiles;
import java.io.IOException;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Filepath;

/**
 * Parses the guidance request the MCP server writes. The file comes
 * from another process that may be older or newer than this plugin, so anything missing, corrupt, or of
 * another schema version reads as "no request" rather than an error: guiding nowhere is harmless, guiding
 * to a misread tile is not.
 */
public class GuidanceRequestReader
{
	private static final int SCHEMA_VERSION = 1;
	private static final int MAX_PLANE = 3;

	/**
	 * @param file the request file
	 * @return the request, or null when there is none or it cannot be trusted
	 */
	public GuidanceRequest read(Filepath file)
	{
		try
		{
			String json = AtomicFiles.read(file);
			return parse(new JsonParser().parse(json).getAsJsonObject());
		}
		catch (IOException | JsonParseException | IllegalStateException | DateTimeParseException e)
		{
			return null;
		}
	}

	private static GuidanceRequest parse(JsonObject root)
	{
		Integer version = wholeNumber(root.get("schemaVersion"));
		JsonElement target = root.get("target");
		JsonElement requestedAt = root.get("requestedAt");
		if (version == null || version != SCHEMA_VERSION || target == null || !target.isJsonObject()
			|| requestedAt == null || !requestedAt.isJsonPrimitive())
		{
			return null;
		}
		WorldPoint point = tile(target.getAsJsonObject());
		if (point == null)
		{
			return null;
		}
		return new GuidanceRequest(point, label(root.get("label")), Instant.parse(requestedAt.getAsString()));
	}

	private static WorldPoint tile(JsonObject target)
	{
		Integer x = wholeNumber(target.get("x"));
		Integer y = wholeNumber(target.get("y"));
		Integer plane = wholeNumber(target.get("plane"));
		if (x == null || y == null || plane == null || x < 0 || y < 0 || plane < 0 || plane > MAX_PLANE)
		{
			return null;
		}
		return new WorldPoint(x, y, plane);
	}

	/**
	 * Gson's {@code getAsInt} silently truncates 1.5 to 1, which would guide to the wrong tile, so whole
	 * numbers are checked explicitly.
	 */
	private static Integer wholeNumber(JsonElement element)
	{
		if (element == null || !element.isJsonPrimitive() || !((JsonPrimitive) element).isNumber())
		{
			return null;
		}
		double value = element.getAsDouble();
		return value == Math.rint(value) && Math.abs(value) <= Integer.MAX_VALUE ? (int) value : null;
	}

	private static String label(JsonElement element)
	{
		return element == null || !element.isJsonPrimitive() ? null : element.getAsString();
	}
}

package com.wiseoldclaude.guidance;

import java.util.Collections;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.util.Text;

/**
 * Draws guidance with what the client already offers instead of a pathfinder of our own: the Shortest Path
 * plugin's route (requested over the same PluginMessage Quest Helper uses) and the game's native hint
 * arrow. The message is always posted, because the event bus delivers it to no one when Shortest Path is
 * not installed, and the hint arrow is always set, so guidance degrades to the arrow alone rather than
 * depending on detecting another plugin. Must be called on the client thread.
 */
public class ClientGuidanceDisplay implements GuidanceDisplay
{
	private static final String SHORTEST_PATH = "shortestpath";
	private static final String PATH = "path";
	private static final String CLEAR = "clear";
	private static final String TARGET = "target";

	private final Client client;
	private final EventBus eventBus;

	/**
	 * @param client the game client, for the hint arrow and chat confirmation
	 * @param eventBus the client's event bus, shared with the Shortest Path plugin
	 */
	@Inject
	public ClientGuidanceDisplay(Client client, EventBus eventBus)
	{
		this.client = client;
		this.eventBus = eventBus;
	}

	/**
	 * Omits Shortest Path's optional {@code start}, so it routes from the player's tile and keeps
	 * recalculating when the player strays, as it does for paths set by hand.
	 */
	@Override
	public void show(GuidanceRequest request)
	{
		Map<String, Object> data = Collections.singletonMap(TARGET, request.getTarget());
		eventBus.post(new PluginMessage(SHORTEST_PATH, PATH, data));
		client.setHintArrow(request.getTarget());
		chat("Guiding you to " + nameOf(request) + ".");
	}

	/**
	 * Leaves Shortest Path's route alone: it ends the route itself near the target, and clearing it here
	 * could wipe a route another plugin set in the meantime.
	 */
	@Override
	public void arrived(GuidanceRequest request)
	{
		clearOwnHintArrow(request.getTarget());
		chat("You have arrived at " + nameOf(request) + ".");
	}

	@Override
	public void withdraw(GuidanceRequest request)
	{
		eventBus.post(new PluginMessage(SHORTEST_PATH, CLEAR));
		clearOwnHintArrow(request.getTarget());
	}

	/**
	 * The game sets hint arrows of its own (quests, tutorials), so only an arrow still pointing at our
	 * target is removed.
	 */
	private void clearOwnHintArrow(WorldPoint target)
	{
		if (client.hasHintArrow() && target.equals(client.getHintArrowPoint()))
		{
			client.clearHintArrow();
		}
	}

	private void chat(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[Wise Old Claude] " + message, null);
	}

	private static String nameOf(GuidanceRequest request)
	{
		WorldPoint target = request.getTarget();
		return request.getLabel() != null
			? Text.escapeJagex(request.getLabel())
			: target.getX() + ", " + target.getY() + " (floor " + target.getPlane() + ")";
	}
}
